/* ===== v67：从地点串里取「市级」。
   旧写法 split(/[·\s]/)[0] 会把「辽宁·沈阳·明德女高」切成「辽宁」，
   于是世间诸方按省算，而不是按城算。 */
function __bhCityOf(s){
  try{
    var t=String(s==null?'':s).trim();
    if(!t || t==='—' || t==='-') return '沈阳';
    var parts=t.split(/[·\s\/｜|,，、]+/).filter(function(x){return x;});
    /* ① 优先：带 市/盟/州/地区 后缀的那一段（去后缀） */
    for(var i=0;i<parts.length;i++){
      var p=parts[i];
      if(/[市盟州]$/.test(p) && p.length>=2) return p.replace(/[市盟州]$/,'');
      if(/地区$/.test(p) && p.length>=3) return p.replace(/地区$/,'');
    }
    /* ② 直辖市与单列：省段之后那一段就是市 */
    if(parts.length>=2){
      var first=parts[0];
      var direct=['北京','天津','上海','重庆'];
      for(var j=0;j<direct.length;j++){ if(first.indexOf(direct[j])>=0) return direct[j]; }
      return parts[1];
    }
    /* ③ 兜底：整段去后缀 */
    return t.replace(/[市盟州]$/,'').replace(/地区$/,'');
  }catch(e){ return '沈阳'; }
}

var BH_EPOCH=Date.UTC(2026,9,25,8,0,0);
var BH_FIXED_FESTIVAL={'01-01':'元旦','02-14':'情人节','05-01':'劳动节','06-01':'儿童节','09-10':'教师节','10-01':'国庆节'};
var BH_LUNAR_FESTIVAL={'正月1':'春节','正月15':'元宵','五月5':'端午','七月7':'七夕','七月15':'中元','八月15':'中秋','九月9':'重阳','腊月8':'腊八','腊月23':'北方小年','腊月24':'南方小年','腊月30':'除夕'};
function bhCalendar(){
 var minutes=Number(V.worldSim&&V.worldSim.clock);if(!Number.isFinite(minutes))minutes=(Number(V.day)||0)*1440;
 var dt=new Date(BH_EPOCH+minutes*60000),y=dt.getUTCFullYear(),m=String(dt.getUTCMonth()+1).padStart(2,'0'),day=String(dt.getUTCDate()).padStart(2,'0'),f=[];
 var fixed=BH_FIXED_FESTIVAL[m+'-'+day];if(fixed)f.push(fixed);
 try{
  var parts=new Intl.DateTimeFormat('zh-CN-u-ca-chinese',{timeZone:'UTC'}).formatToParts(dt),lm='',ld='';
  parts.forEach(function(x){if(x.type==='month')lm=x.value;if(x.type==='day')ld=x.value;});
  var lunar=BH_LUNAR_FESTIVAL[lm+ld];if(lunar&&f.indexOf(lunar)<0)f.push(lunar);
  var next=new Date(dt.getTime()+86400000),np=new Intl.DateTimeFormat('zh-CN-u-ca-chinese',{timeZone:'UTC'}).formatToParts(next),nl='',ny='';
  np.forEach(function(x){if(x.type==='month')nl=x.value;if(x.type==='relatedYear')ny=x.value;});
  if(lm==='腊月'&&nl==='正月'&&f.indexOf('除夕')<0)f.push('除夕');
 }catch(e){}
 return {date:y+'年'+Number(m)+'月'+Number(day)+'日',festival:f.join(' · ')||'普通日'};
}
window.__bhCalendar=bhCalendar;
function pick(o,k,d){ return (o && o[k]!==undefined && o[k]!==null && o[k]!=='') ? o[k] : d; }
function arr(v){ return Array.isArray(v) ? v : (v ? [v] : []); }
function esc(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); }
