/* ---------- 默认展开（BH_DEFAULT_OPEN）：UI 面板固定打开，可手动收 ---------- */
try{
  var _bh=document.getElementById('bh');
  if(_bh){ _bh.classList.add('open'); _bh.setAttribute('data-open','1'); }
}catch(e){}


/* ---------- BH_WRAP_PGS：把全部页签包进 .bh-pgs，让头部/页签/锚点固定，仅内容区滚动 ---------- */
function bhWrapPgs(){
  try{
    var pnl = document.getElementById('pnl') || document.querySelector('.bh-p');
    if(!pnl) return null;
    var box = pnl.querySelector(':scope > .bh-pgs');
    if(!box){
      box = document.createElement('div');
      box.className = 'bh-pgs';
      var pgs = pnl.querySelectorAll(':scope > .bh-pg');
      for(var i=0;i<pgs.length;i++) box.appendChild(pgs[i]);
      var ft = pnl.querySelector(':scope > .bh-f2') || pnl.querySelector(':scope > footer');
      if(ft) pnl.insertBefore(box, ft); else pnl.appendChild(box);
    }
    return box;
  }catch(e){ return null; }
}
window.bhWrapPgs = bhWrapPgs;
bhWrapPgs();

var BOOK_OPEN = false;   /* 真形图默认只铺前 8 张，点尾巴展开 */
function renderBook(){
  var box = document.getElementById('book');
  /* 未契约/未遇到的先不进真形图，避免提前看到头像、名字与案底 */
  var _bk=(V.book||[]).filter(function(b){
    var s=typeof b==='string'?'':(b.s||b.stage||'');
    return String(s||'').trim() && String(s).trim()!=='未契约';
  });
  if(!_bk.length){ box.innerHTML = '<div class="bh-empty">《百鬼真形图》尚空 · 待合资格者自愿结契</div>'; return; }
  function stageCls(s){
    if(/立契|同行/.test(s)) return 's4';
    if(/信任/.test(s)) return 's3';
    if(/合作/.test(s)) return 's2';
    return 's1';
  }
  var CAP = 8, all = _bk, shown = BOOK_OPEN ? all : all.slice(0, CAP);
  box.innerHTML = shown.map(function(b){
    var n = typeof b === 'string' ? b : (b.n || b.name || '');
    var d = typeof b === 'string' ? '' : (b.d || b.desc || '');
    var s = typeof b === 'string' ? '' : (b.s || b.stage || '');
    if(/索命|破身|缠榻|本命|归顺/.test(s)) s='旧关系待核';
    var r = typeof b === 'string' ? '' : (b.r !== undefined ? b.r : (b.rel !== undefined ? b.rel : ''));
    var cls = stageCls(s);
    var gcmd = '感应真形：' + n + (s ? '｜' + s : '');
    var rn = r === '' ? null : Math.max(0, Math.min(100, Number(r) || 0));
    var _rows=[["阶段",s||"在册"],["信任",(rn===null?"—":rn)],["案底",d||"未记"]];
    var pImg = (typeof avatarFor==='function') ? (avatarFor(n)||'') : '';
    var pFull = (typeof portraitFor==='function') ? (portraitFor(n)||'') : '';
    var imgThumb = pImg ? ('<div style="flex:0 0 54px;height:72px;border-radius:2px;overflow:hidden;border:1px solid rgba(216,180,90,.35);background:linear-gradient(135deg,rgba(216,180,90,.08),rgba(0,0,0,.6));flex-shrink:0"><img src="'+esc(pImg)+'" style="width:100%;height:100%;object-fit:cover;object-position:top center" alt="'+esc(n)+'" ></div>') : '';
    var bAct = '我唤出「' + n + '」，想对她：';
    var html = '<div class="bk ' + cls + '" data-det="' + encodeURIComponent(n) + '" data-rows="' + encodeURIComponent(JSON.stringify(_rows)) + '" data-act="' + esc(bAct) + '" data-act-label="唤出互动 · 写草稿 ▸"' + (pFull?(' data-img="'+esc(pFull)+'"'):'') + ' role="button" tabindex="0">';
    if(pImg){
      html += '<div style="display:flex;gap:10px;align-items:flex-start">';
      html += imgThumb;
      html += '<div style="flex:1;min-width:0">';
    }
    html += '<div class="bk-h"><span class="bk-n">' + esc(n) + '</span>';
    if(s) html += '<span class="bk-s">' + esc(s) + '</span>';
    html += '</div>';
    if(d) html += '<div class="bk-d">' + esc(d) + '</div>';
    if(rn !== null){
      html += '<div class="bk-bar"><i style="width:' + rn + '%"></i></div>';
      html += '<div class="bk-f"><span>信任</span><b>' + rn + '</b></div>';
    }
    if(pImg) html += '</div></div>';
    html += '</div>';
    return html;
  }).join('')
  + (all.length > CAP
      ? '<div class="gh-more" id="bkMore" role="button" tabindex="0">'
        + (BOOK_OPEN ? ('收起 · 只留前 ' + CAP + " 张 ▴") : ('展开全部 ' + all.length + " 张 ▾"))
        + '</div>'
      : '');
  /* 立绘预加载：点开详情前先缓存，避免弹层里空白等图 */
  try{
    [].forEach.call(box.querySelectorAll('.bk[data-img]'), function(el){
      var u=el.getAttribute('data-img'); if(!u) return;
      var im=new Image(); im.src=u;
    });
  }catch(e){}

  var bm = document.getElementById('bkMore');
  if(bm) bm.addEventListener('click', function(){
    BOOK_OPEN = !BOOK_OPEN;
    try{ renderBook(); }catch(e){}
  });
}

var BAG_CAT='';
function renderBag(){
  var bag=document.getElementById('bag'), cash=document.getElementById('cash');
  if(!V.bag.length){ bag.innerHTML='<div class="bh-empty">行囊空空</div>'; }
  else{
    var order=[], groups={};
    V.bag.forEach(function(b){
      var k=typeof b==='string'?'物':(b.k||b.key||'物');
      if(!groups[k]){ groups[k]=[]; order.push(k); }
      groups[k].push(b);
    });
    if(!BAG_CAT || !groups[BAG_CAT]) BAG_CAT=order[0];
    var tabs='<div class="bag-tabs" role="tablist">'+order.map(function(k){
      return '<button type="button" class="bag-tab'+(k===BAG_CAT?' on':'')+'" data-bagcat="'+esc(k)+'" role="tab" aria-selected="'+(k===BAG_CAT)+'">'+esc(k)+'<i>'+groups[k].length+'</i></button>';
    }).join('')+'</div>';
    var cells='<div class="bag-grid">'+groups[BAG_CAT].map(function(b){
      var v=typeof b==='string'?b:(b.v||b.val||'');
      var m=String(v).match(/^(.*?)\s*[x×]\s*(\d+)\s*$/i);
      var name=m?m[1]:v, num=m?m[2]:'';
      var use=(typeof b==='object'&&(b.u||b.use))?String(b.u||b.use):'';
      var _r=[['类别',BAG_CAT],['数量',num||'1'],['用途',use||'按物性使用'],['状态','随身 · 可用']];
      return '<div class="bag-cell" data-det="'+encodeURIComponent(name)+'" data-rows="'+encodeURIComponent(JSON.stringify(_r))+'" data-act="'+esc('我取出随身的「'+name+'」细看或动用：')+'" data-act-label="取出动用 · 写草稿 ▸" role="button" tabindex="0">'
        +(num?'<span class="bag-n">×'+esc(num)+'</span>':'')
        +'<span class="bag-v">'+esc(name)+'</span>'
        +'<span class="bag-u">'+esc(use||'按物性使用')+'</span></div>';
    }).join('')+'</div>';
    bag.innerHTML=tabs+cells;
    if(!bag.__bagBound){
      bag.__bagBound=true;
      bag.addEventListener('click',function(e){
        var tab=e.target.closest?e.target.closest('.bag-tab'):null;
        if(!tab) return;
        BAG_CAT=tab.getAttribute('data-bagcat');
        try{ renderBag(); }catch(err){}
      });
    }
  }
  if(!V.cash.length){ cash.innerHTML=''; }
  else{
    cash.innerHTML='<div class="bag-money">'+V.cash.map(function(c){
      var k=typeof c==='string'?'':(c.k||c.key||'');
      var v=typeof c==='string'?c:(c.v||c.val||'');
      return '<span class="bag-m"><i>'+esc(k)+'</i><b>'+esc(v)+'</b></span>';
    }).join('')+'</div>';
  }
}

function renderTrack(){
  var box = document.getElementById('target');
  var t = null;
  for(var i=0;i<V.book.length;i++){
    var b = V.book[i]; if(typeof b!=='object') continue;
    var s = String(b.s || b.stage || '').trim();
    if(!s || s==='未契约') continue;
    if(!/本命|归顺|契约/.test(s)){ t = b; break; }
  }
  var html = '';
  if(!t){
    html = '<div class="bh-empty">尚无在册目标 · 待开卷</div>';
  }else{
    var n = t.n || t.name || '', s = t.s || t.stage || '', d = t.d || t.desc || '';
    html = '<div class="bh-trk-card">'
      + '<div class="bh-trk-h"><span class="bh-trk-n">'+esc(n)+'</span>'
      + (s?'<span class="bh-trk-s">'+esc(s)+'</span>':'')+'</div>'
      + '<div class="bh-trk-r"><span>所在</span><b>'+esc(V.loc||'—')+'</b></div>'
      + '<div class="bh-trk-r"><span>特征</span><b>'+esc(d||'—')+'</b></div>'
      + ((t.r !== undefined && t.r !== '') ? ('<div class="bk-bar" style="margin-top:6px"><i style="width:'
          + Math.max(0, Math.min(100, Number(t.r) || 0)) + '%"></i></div>'
          + '<div class="bk-f"><span>依恋</span><b>' + Math.round(Number(t.r) || 0) + '</b></div>') : '')
      + '<button type="button" class="trk-go" data-go="' + esc('针对「'+n+'」，我动身前往「'+(V.loc||'')+'」一带察看动静：') + '">前往察看 ›</button>'
      + '</div>';
  }
  box.innerHTML = html;

  var ob = document.getElementById('omen');
  if(!V.omen.length){ ob.innerHTML = ''; }
  else{
    /* omen 是 {k:"凶|兆|吉|应", v:"可观察现象"} 结构，旧代码直接 esc(o) 把对象串成 [object Object] */
    var OC={'凶':'#D9432F','兆':'#C29449','吉':'#8FD9B4','应':'#8FAECC'};
    ob.innerHTML = '<div class="bh-omen-h">凶 兆</div><div class="bh-chips">' + V.omen.map(function(o){
      var k='', v='';
      if(o && typeof o==='object'){ k=String(o.k||o.type||''); v=String(o.v||o.text||o.d||''); }
      else { v=String(o==null?'':o); }
      if(!v.trim()) return '';
      var c=OC[k]||'#C29449';
      var tag = k ? '<i class="bh-chip-k" style="color:'+c+'">'+esc(k)+'</i>' : '';
      return '<span class="bh-chip" style="border-color:'+c+'44;color:#2B221A">'
        + tag + esc(v) + '</span>';
    }).join('') + '</div>';
  }
}

var picked = [];
function renderOpts(){
  var box = document.getElementById('optGrid');
  var oc = document.getElementById('opCnt');
  if(oc) oc.textContent = (V.adv||[]).length ? ((V.adv||[]).length+' 项建议 · 可自拟') : '自由手写';
  if(!box) return;
  if(!(V.adv||[]).length){ V._cand=[];picked=[];box.innerHTML='<div class="bh-empty">暂无行动建议，可在下方自行输入。</div>';return; }
  box.innerHTML = V.adv.map(function(a,i){
    var k = typeof a==='string' ? '' : (a.k||a.key||'');
    var v = typeof a==='string' ? a : (a.v||a.val||'');
    var on = picked.indexOf(i) >= 0;
    return '<button type="button" class="bh-op'+(on?' on':'')+'" data-i="'+i+'">'
      + '<span class="bh-op-n">'+(i+1)+'</span>'
      + '<span class="bh-op-t">'+esc(k?(k+' · '+v):v)+'</span></button>';
  }).join('');
}
function qpickLines(){
  var _src = (V.adv && V.adv.length) ? V.adv : (V._cand || []);
  return picked.map(function(i){
    var a = _src[i]; if(!a) return '';
    var k = typeof a==='string' ? '' : (a.k||a.key||'');
    var v = typeof a==='string' ? a : (a.v||a.val||'');
    return (picked.indexOf(i)+1) + '. ' + (k?(k+'｜'+v):v);
  }).filter(Boolean);
}
/* 只重排选项部分，DRAFT（手打内容）原样保留并接在后面 */
function syncSend(pushHost){
  var ta = document.getElementById('sbTa');
  if(!ta) return;
  var lines = qpickLines();
  var body = lines.join('\n');
  if(DRAFT) body = body ? (body + '\n' + DRAFT) : DRAFT;
  ta.value = body;
  document.getElementById('sbCnt').textContent = picked.length ? ('已选 '+picked.length) : (DRAFT ? '手写中' : '未选');
  var hint = picked.length ? '已选 '+picked.length+' 条 · 可继续点选或改写' : (DRAFT ? '手写草稿中' : '点选项生成草稿');
  /* 指令草稿模式：任何选项点击都只写草稿，绝不自动写宿主输入框 */
  document.getElementById('sbHint').textContent = hint;
  document.getElementById('sbGo').disabled = !ta.value.trim();
}
/* 用户手动改输入框：把「选项行之后的内容」记为 DRAFT */
function syncDraftFromTextarea(){
  var ta = document.getElementById('sbTa'); if(!ta) return;
  var v = ta.value || '';
  var lines = qpickLines();
  var body = lines.join('\n');
  if(!body){ DRAFT = v; return; }
  if(v.indexOf(body) === 0){
    DRAFT = v.slice(body.length).replace(/^\n/, '');
  }else{
    /* 用户把选项行也改了：整段当手写，选项选择作废 */
    DRAFT = v;
    picked = [];
  }
}
/* 涌现条目只有一种形状（S61 二）：
     { id:'E0007', n:'辽宁·沈阳·西城废站', c:'沈阳市', k:'恶厉',
       type:'new'|'mut'|'wild', s:1–5, g:'域规一句', d:'一句话简述' }
   k 是阶位（六阶之一），type 才是种类。旧代码把 k 当种类用，
   于是界面上所有凶域都被贴成「新域」，阶位全丢。 */
var EMGTYPE = { new:'新域', mut:'异变', wild:'野鬼' };
var EMG_OPEN = true;   /* 涌现块默认收起：一行标题，点开才铺条目 */
function renderEmg(){
  var box = document.getElementById('emg');
  if(!box) return;
  var list = V.emg||[];
  if(!list.length){ box.hidden=true; box.innerHTML=''; return; }
  box.hidden=false;
  var quota = '';
  try{
    var et=V.emgTurn||{}, r=Number(et.round)||0;
    var l10=(Array.isArray(et.last10)?et.last10:[]).filter(function(z,i,a){var n=Number(String(z).replace(/^r/,''));return /^r\d+$/.test(String(z))&&n>=Math.max(0,r-9)&&n<=r&&a.indexOf(z)===i;});
    var used=l10.filter(function(z){ return String(z)===('r'+r); }).length;
    quota = ' · 常规新增配额：本轮 '+(used?'1/1':'0/1')+' · 近十轮 '+l10.length+'/3';
  }catch(e){}
  /* 一张图铺开就是五百多处，全刷出来就是一面墙。
     只留最近 4 条，其余给一行计数——细节交给舆图与城市志。 */
  var CAP = 4, total = list.length;
  var show = list.slice(Math.max(0, total - CAP));
  var html='<div class="bh-emg-h" role="button" tabindex="0"><i></i>地脉异动 · 已登记凶域'
    +'<span class="bh-emg-n">'+total+' 处现存</span><span class="bh-emg-ar">▼</span></div>'
    +'<div class="bh-emg-b"><div class="bh-quota">实时同步正文已探知凶域与现场显形鬼口（点选可看域规或直接前往勘察）</div>';
  show.forEach(function(e){
    var ty = EMGTYPE[e.type] ? e.type : (EMGTYPE[e.k] ? 'new' : 'new');
    var kn = EMGTYPE[ty];
    var lv = (EMGTYPE[e.k] ? '' : String(e.k||''));
    html += '<div class="bh-e" data-det="'+encodeURIComponent('凶域 · '+(e.n||''))+'" data-rows="'
      + encodeURIComponent(JSON.stringify([
          ['所在', String(e.c||'')],
          ['煞阶', lv || '—'],
          ['来历', kn],
          ['域规', String(e.g||'—')],
          ['简述', String(e.d||'—')]
        ])) + '" role="button" tabindex="0"><div class="bh-e-t">';
    html += '<span class="bh-e-k '+esc(ty)+'">'+kn+'</span>';
    if(lv) html += '<span class="bh-e-lv">'+esc(lv)+'</span>';
    html += '<span class="bh-e-n">'+esc(e.n||'')+'</span>';
    if(e.s) html += '<span class="bh-e-s">'+star(e.s)+'</span>';
    html += '</div>';
    html += '</div>';
  });
  if(total > CAP) html += '<div class="bh-e" style="justify-content:center;color:#6E5D4B;font-size:10.5px">另有 '+(total-CAP)+' 处 · 舆图点省可查</div>';
  html += '</div>';
  box.innerHTML = html;
  if(EMG_OPEN) box.classList.add('on');
  var _eh = box.querySelector('.bh-emg-h');
  if(_eh) _eh.addEventListener('click', function(){
    box.classList.toggle('on');
    EMG_OPEN = box.classList.contains('on');
  });
}


function renderOut(){
 var box=document.getElementById('out');if(!box)return;
 var rows=(V.out||[]).map(function(o){return typeof o==='string'?o:(o.v||o.d||o.desc||'');}).filter(Boolean);
 box.hidden=!rows.length;box.innerHTML=rows.length?'<div class="bh-out-h">已知远方消息</div><div class="bh-out-b">'+rows.map(function(t){return '<div class="bh-out-r">'+esc(t)+'</div>';}).join('')+'</div>':'';
 box.classList.add('on');
}

function closeDet(){ var d=document.getElementById("det"); if(d) d.hidden=true; }
window.showDet=showDet; window.closeDet=closeDet;

var FTINFO={"本境修持": [["含义", "当前境界的修持积累（0–100）"], ["突破", "满100代表积累足够，还需掌握本境关键能力并通过具体条件验证"]], "功德": [["含义", "护生、济困与平定异样的善业积累"], ["实效", "≥100 易得城隍古刹与正统高功感应相助，温养化怨损耗减轻；≤-100 正道疏远、灵物晦暗、易遭反噬"]], "阳寿": [["含义", "生命本源刻度（0–1000）"], ["实效", "≤200 气血衰败、不可强施耗命重术；归零则身死"]], "阴蚀": [["含义", "阴煞入体深浅（0–1000）"], ["实效", "≥300 畏寒麻木；≥600 视觉叠影、五维受抑，须靠调息、汤药或温魂贡香拔除"]], "暴露": [["含义", "在公众、警方与特调局眼中的显眼度"], ["实效", "100+ 片警与记者留心；300+ 特调局与刑侦立线核查；600+ 重点盯防与通行受限"]], "人情债": [["含义", "欠同行、街坊与势力的待偿承诺"], ["实效", "≥200 债主会在关键节点催讨或夹带条件；拖欠不还则同圈拒帮"]], "阴债": [["含义", "接下遗愿典当或动用阴物未了的冥途因果"], ["实效", "子夜与节令引旧主叩门催问；≥300 压迫调息、易招同类怨念"]], "声望": [["含义", "同行与街面口碑（-1000–1000）"], ["实效", "≤-100 拒借器物且压价三成；0–99 按市价现结；≥100 留罕物、通消息、可挂账；≥300 跨省引荐与前辈给面"]]};

function readCultivation(){
 if(window.__bhDemo && window.__bhDemo.cultivation){
   return window.__bhDemo.cultivation;
 }
 var el=document.getElementById('v-cultivationRaw');
 var fallbackStage = (window.__bhV && window.__bhV.realm && String(window.__bhV.realm).trim() && !/^\{\{/.test(String(window.__bhV.realm))) ? String(window.__bhV.realm).trim() : '未入门';
 try{
   var rawTxt = el ? String(el.value||'').trim() : '';
   if(rawTxt && rawTxt.charAt(0)==='{'){
     var c = JSON.parse(rawTxt);
     if(c && typeof c==='object'){
       var st = String(c.stage || fallbackStage || '未入门').trim();
       var pr = Number(c.progress);
       if(!isFinite(pr)) pr = 0;
       return {
         version: 1,
         stage: st.slice(0, 24),
         progress: Math.max(0, Math.min(100, pr)),
         path: String(c.path || ''),
         skills: Array.isArray(c.skills) ? c.skills : [],
         proofs: Array.isArray(c.proofs) ? c.proofs : [],
         bottleneck: String(c.bottleneck || ''),
         migration: String(c.migration || 'new')
       };
     }
   }
 }catch(e){}
 return {stage:fallbackStage,progress:0,path:'',skills:[],proofs:[],bottleneck:''};
}
function renderCult(){
  var host=document.getElementById('ftCult'); if(!host) return;
  var c=readCultivation();
  var st=String(c.stage==null?'未入门':c.stage);
  var pr=Number(c.progress); if(!isFinite(pr)) pr=0;
  pr=Math.max(0,Math.min(100,Math.round(pr)));
  var KNW=['未入门','感应','养炁','立坛','通幽','镇域','合道'];
  var idx=KNW.indexOf(st);
  var unknown = (st==='境界待核');
  var tail = unknown ? '待核' : (idx>=0 ? ('第 '+(idx+1)+' / 7 境') : '已越合道 · 破限境');
  var badge = (!unknown && idx<0) ? '<span style="color:#C89B3C;font-size:9px;letter-spacing:.1em;margin-left:5px">破限</span>' : '';
  var path = String(c.path||'').trim();
  var bog  = String(c.bottleneck||'').trim();
  var sks  = Array.isArray(c.skills) ? c.skills.filter(Boolean) : [];
  var pfs  = Array.isArray(c.proofs) ? c.proofs.filter(Boolean) : [];
  var brief = unknown ? '' : ((bog && bog!=='无') ? bog : (path||'未定功法路数'));
  if(brief.length>44) brief = brief.slice(0,44)+'…';
  var cultAct = (st==='未入门' && !path)
    ? '我想找门路修持吐纳入门（查阁中旧札、访当地道观散修或借合修引气）：'
    : ('我静心按「'+(path||'本门路数')+'」吐纳调息、打磨修持与五维：');
  var rows=[
    ['境界',st + '（'+tail+'）'],
    ['本境修持',pr+' / 100'],
    ['所修法门',path||'尚未习得正式法门（可翻阁中残卷、拜访道观散修、或借特调局/阴煞合修引气入门）'],
    ['已掌术法',sks.length ? sks.join('、') : '尚无'],
    ['已证关窍',pfs.length ? pfs.join('；') : '尚无'],
    ['当前卡点',bog||'无'],
    ['晋升律','须有明确法门/引路人，经吐纳锤炼、实案交锋或合修实证方可破境；五维与境界皆上不封顶']
  ];
  host.innerHTML='<div class="ft-sub">境 界 · 修 持</div>'
    + '<div class="ft-r" role="button" tabindex="0" data-det="'+esc(st)+'" data-rows="'+encodeURIComponent(JSON.stringify(rows))+'" data-act="'+esc(cultAct)+'" data-act-label="静修打磨 ▸">'
    +   '<span class="ft-k">'+esc(st)+'</span>'
    +   '<span class="ft-b"><i style="width:'+pr+'%;background:'+(idx<0?'#C89B3C':'#8C6A2A')+'"></i></span>'
    +   '<b class="ft-v">'+pr+'</b></div>'
    + '<div class="ft-note">'+tail+badge+(brief?(' · '+esc(brief)):'')+(sks.length?(' · 已学 '+sks.length+' 术'):'')+'</div>';
}

function renderFate(){
  var a=document.getElementById('ftA'); if(!a) return 0;
  var warn=0;
  /* 每根条必须传自己的量纲上限：功德/声望是 −1000–1000，其余 0–1000。
     旧写法一律按 1000 满画，负功德会画成 0 宽、阴债根本没上过面板。 */
  function bar(lb,v,max,bad,floor){
    v=Number(v)||0; max=Number(max)||1000;
    floor=(floor===undefined)?0:Number(floor);
    /* 上不封顶：数值超出量纲按千位扩尺，避免超限后永远满格 */
    if(floor>=0 && v>max){ max=Math.ceil(v/1000)*1000; }
    var _cap = Math.max(1000, Math.ceil(Math.abs(v)/1000)*1000);
    var span=max-floor;
    var p=span?Math.max(0,Math.min(100,Math.round((v-floor)/span*100))):0;
    var hot = bad && p>=60;
    var col = hot ? '#D9432F' : (p>=80?'#C89B3C':'#8C6A2A');
    /* 双极刻度（功德／声望，−1000–1000）：从正中往两边长，
       否则「0」会画成半根满条，看着像还有一半的家底。 */
    var bi = floor<0;
    var barHtml;
    if(bi){
      var half=Math.abs(v)/_cap*50;
      var left = v>=0 ? 50 : (50-half);
      if(v<0) col='#7A5C8C';
      barHtml='<span style="flex:1;min-width:0;position:relative;height:6px;background:rgba(255,255,255,.07);border-radius:3px;overflow:hidden">'
        +'<i style="position:absolute;left:50%;top:0;bottom:0;width:1px;background:rgba(255,255,255,.18)"></i>'
        +'<i style="display:block;position:absolute;top:0;bottom:0;left:'+left+'%;width:'+half+'%;background:'+col+'"></i></span>';
    }else{
      barHtml='<span style="flex:1;min-width:0;height:6px;background:rgba(255,255,255,.07);border-radius:3px;overflow:hidden">'
        +'<i style="display:block;height:100%;width:'+p+'%;background:'+col+'"></i></span>';
    }
    var _inf = FTINFO[lb] || [['说明','—']];
    var vs = String(v);
    return '<div data-det="' + lb + '" data-rows="' + encodeURIComponent(JSON.stringify(_inf)) + '"'
      + ' role="button" tabindex="0" style="display:flex;align-items:center;gap:8px;margin:0 11px 7px;cursor:pointer">'
      +'<span style="flex:0 0 52px;font-size:12px;color:#3A2F24">'+lb+'</span>'
      + barHtml
      +'<b style="flex:0 0 42px;text-align:right;font:800 13px/1 ui-monospace,monospace;color:'+(hot?'#E0705A':'#DCD0B8')+'">'+vs+'</b></div>';
  }
  /* 每根条一套「名称 / 条 / 数值」，字号降到 11px 与卷宗一致 */
  function row(lb, v, max, bad, floor){
    v=Number(v)||0; max=Number(max)||1000;
    floor=(floor===undefined)?0:Number(floor);
    /* 上不封顶：数值超出量纲按千位扩尺，避免超限后永远满格 */
    if(floor>=0 && v>max){ max=Math.ceil(v/1000)*1000; }
    var _cap = Math.max(1000, Math.ceil(Math.abs(v)/1000)*1000);
    var span=max-floor;
    var p=span?Math.max(0,Math.min(100,Math.round((v-floor)/span*100))):0;
    var hot = bad && p>=60;
    var col = hot ? '#D9432F' : (p>=80?'#C89B3C':'#8C6A2A');
    var bi = floor<0;
    var inner;
    if(bi){
      var half=Math.abs(v)/_cap*50;
      var left = v>=0 ? 50 : (50-half);
      if(v<0) col='#7A5C8C';
      inner='<span class="ft-b"><i class="ft-mid"></i><i style="left:'+left+'%;width:'+half+'%;background:'+col+'"></i></span>';
    }else{
      inner='<span class="ft-b"><i style="width:'+p+'%;background:'+col+'"></i></span>';
    }
    var _inf = FTINFO[lb] || [['说明','—']];
    var vs = String(v);
    return '<div class="ft-r" data-det="'+lb+'" data-rows="'+encodeURIComponent(JSON.stringify(_inf))+'" role="button" tabindex="0">'
      + '<span class="ft-k">'+lb+'</span>' + inner
      + '<b class="ft-v'+(hot?' hot':'')+'">'+vs+'</b></div>';
  }
  var _cu = readCultivation();
  var lf=document.getElementById('ftLife');
  if(lf) lf.innerHTML = row('阳寿', V.life, 1000, false);
  a.innerHTML = row('功德', V.merit, 1000, false, -1000)
    + row('声望', V.rep, 1000, false, -1000);
  var b=document.getElementById('ftB');
  if(b) b.innerHTML = row('阴蚀',V.erode,1000,true)+row('暴露',V.expose,1000,true)+row('人情债',V.debt,1000,true)
    +row('阴债',V.yinzhai,1000,true)
    +(V.foe&&V.foe.length?('<div class="ft-foe"><span>仇家在册</span><b>'+V.foe.length+' 位</b></div>'):'');

  if(V.life<=200||V.expose>=600||V.erode>=600||V.debt>=1000||V.yinzhai>=300) warn=1;
  var s=document.getElementById('ftSum');
  if(s){ s.textContent = warn?'凶':'平'; s.style.color = warn?'#D9432F':'#7C8F6B'; }
  var stag=document.getElementById('ftSumTag');
  if(stag){ stag.textContent = warn?'命途告警':'气脉平稳'; stag.style.color = warn?'#E0705A':'#8FC7B6'; }
  var alive = '镇杀记录 '+V.kcount;
  var st=document.getElementById('ftTip');
  if(st) st.textContent = '度化 '+V.spirit+' ｜ '+alive+' ｜ '+(warn?'命数垂危，宜收缩蛰伏':'命数平稳');
  return warn?1:0;
}


/* 鬼口筛选态：本省（默认）/ 已知 / 全部 */
var GH_FILTER = 'prov';
var GH_VIEW = 'line';   /* line 名条（默认，一屏更多）/ card 详卡 */
var GH_LV = '';         /* 阶位筛选：'' 不过滤 */
var GH_Q = '';          /* 关键词：落点恒可搜；名讳/规则/死角仅对已探知生效 */
var GH_PAGE = 20;
var GH_SHOWN = 20;
function ghPageSize(){ return GH_VIEW==='card' ? 6 : 20; }
function ghProvOf(x){
  var p=String(x.p||'').trim(), o=String(x.owner||'').trim();
  var suf=/(壮族自治区|回族自治区|维吾尔自治区|自治区|特别行政区|省|市)$/;
  var i=p.indexOf('·');
  if(i>0){
    var seg=p.slice(0,i).replace(suf,'');
    for(var ui=0;ui<UPROV.length;ui++){
      var pn=String(UPROV[ui].n||'').replace(suf,'');
      if(seg===pn || seg===UPROV[ui].a) return pn;
    }
  }
  var hay=p+' '+o;
  for(var ui2=0;ui2<UPROV.length;ui2++){
    var pn2=String(UPROV[ui2].n||'').replace(suf,'');
    if(pn2 && hay.indexOf(pn2)>=0) return pn2;
  }
  var cs=(typeof cityList==='function')?cityList():[];
  var best='', bestLen=0;
  for(var ci=0;ci<cs.length;ci++){
    var c=cs[ci], nm=String(c.n||''), core=nm.replace(/(市|县|地区|盟|州)$/,'');
    if(core.length>=2 && hay.indexOf(core)>=0 && core.length>bestLen){
      best=String(c.p||'').replace(suf,'');
      bestLen=core.length;
    }
  }
  if(best) return best;
  var OWN={'沈阳':'辽宁','大连':'辽宁','鞍山':'辽宁','抚顺':'辽宁','盘锦':'辽宁','辽阳':'辽宁',
    '本溪':'辽宁','丹东':'辽宁','锦州':'辽宁','营口':'辽宁','阜新':'辽宁','朝阳':'辽宁','铁岭':'辽宁','葫芦岛':'辽宁',
    '北京':'北京','天津':'天津','上海':'上海','重庆':'重庆'};
  for(var k in OWN){ if(hay.indexOf(k)>=0) return OWN[k]; }
  return '';
}
var LVNUM={'游魂':0,'怨煞':200,'恶厉':400,'红衣':600,'罗刹':800,'鬼王':900,'鬼仙':1000,'冥尊':1000,'天灾':3000,'鬼祖':10000};
function ghLvName(x){
  /* 判等级看 x.s（煞阶 0–1000）；x.k 是文本阶位，两者都有时以数值为准 */
  var st=Number(x.s);
  if(!isFinite(st)||st<=0){ st=LVNUM[x.k]||0; }
  return rankName(st);
}
function ghIsUnk(v){
  var t=String(v||'').trim();
  return !t || t==='—' || t==='-' || /^(未知|不明|未明|待查|（未探知）|\?\?\?|？？？)$/.test(t);
}
function ghIsKnown(x){
  if(!x) return false;
  var k=String(x.k||'').trim();
  if(k==='已知'||k==='已明'||k==='已探') return true;
  return !ghIsUnk(x.n) && (!ghIsUnk(x.r) || !ghIsUnk(x.w));
}
function ghReset(){ GH_SHOWN = GH_PAGE = ghPageSize(); }
function ghSetFilter(f){ GH_FILTER = f; ghReset(); try{ renderGhost(); }catch(e){} }
function ghSetView(v){ GH_VIEW = (v==='card')?'card':'line'; ghReset(); try{ renderGhost(); }catch(e){} }
function ghSetLv(k){ GH_LV = (GH_LV===k)?'':k; ghReset(); try{ renderGhost(); }catch(e){} }
function ghSetQ(q){
  GH_Q = String(q||''); ghReset();
  try{ renderGhost(); }catch(e){}
  /* innerHTML 重渲染会丢焦点：找回搜索框并把光标放回末尾 */
  var inp = document.getElementById('ghQ');
  if(inp){ inp.focus(); try{ inp.setSelectionRange(inp.value.length, inp.value.length); }catch(e){} }
}
window.__bhGhostFilter = ghSetFilter;
function renderGhost(){
  var box=document.getElementById('ghList'); if(!box) return 0;
  var g=V.ghost||[], s='';
  /* --- 筛选 --- */
  var cur = (typeof curLoc==='function') ? (curLoc()||{}) : {};
  var pSuf = /(壮族自治区|回族自治区|维吾尔自治区|自治区|特别行政区|省|市)$/;
  var myProv = String(cur.prov||'').replace(pSuf,'');
  if(!myProv){
    var vl = String((V.loc&&V.loc!=='—')?V.loc:'');
    var pm = vl.match(/^(..省|北京|天津|上海|重庆|内蒙古|广西|西藏|宁夏|新疆|香港|澳门|台湾)/);
    if(pm) myProv = pm[1].replace(pSuf,'');
    if(!myProv && V.city){
      var cc = (typeof cityByName==='function') ? cityByName(String(V.city)) : null;
      if(cc){ myProv = String(cc.p||'').replace(pSuf,''); }
    }
  }
  var all = g.slice().sort(function(a,b){return (Number(b.s)||0)-(Number(a.s)||0);});
  var provList = myProv ? all.filter(function(x){ return ghProvOf(x) === myProv; }) : [];
  var effFilter = GH_FILTER;
  if(effFilter==='prov' && (!myProv || !provList.length)){
    effFilter = all.length ? 'all' : 'prov';
  }
  var secEl = document.getElementById('ghSecH');
  if(secEl){
    if(effFilter==='prov' && myProv){ secEl.textContent = '本 省 在 册 · ' + myProv; }
    else if(effFilter==='known'){ secEl.textContent = '已 知 在 册'; }
    else if(GH_FILTER==='prov' && myProv && !provList.length && all.length){ secEl.textContent = '四 方 在 册（' + myProv + '暂无）'; }
    else { secEl.textContent = all.length ? '四 方 在 册' : '在 册 鬼 口'; }
  }
  var view = all;
  if(effFilter==='prov' && myProv){
    view = provList;
  }else if(effFilter==='known'){
    view = all.filter(ghIsKnown);
  }
  if(GH_LV){
    view = view.filter(function(x){ return ghLvName(x) === GH_LV; });
  }
  if(GH_Q){
    var _q = GH_Q.toLowerCase();
    view = view.filter(function(x){
      if(String(x.p||'').toLowerCase().indexOf(_q) >= 0) return true;
      if(String(x.t||'').toLowerCase().indexOf(_q) >= 0) return true;
      if(!ghIsUnk(x.n) && String(x.n||'').toLowerCase().indexOf(_q) >= 0) return true;
      if(ghIsKnown(x)){
        return (String(x.r||'')+' '+String(x.w||'')+' '+String(x.job||'')).toLowerCase().indexOf(_q) >= 0;
      }
      return false;
    });
  }
  var total = view.length;
  var page = view.slice(0, GH_SHOWN);
  /* --- 筛选条 --- */
  function fbtn(k, label, n){
    var on = (effFilter===k);
    return '<span class="gh-f'+(on?' on':'')+'" data-f="'+k+'" role="button" tabindex="0">'
      + label + (n!=null?' <i>'+n+'</i>':'') + '</span>';
  }
  var knAll = all.filter(ghIsKnown).length;
  var bar = '<div class="gh-fs" id="ghFs">'
    + (myProv && provList.length ? fbtn('prov','本省·'+myProv, provList.length) : '')
    + fbtn('known','已知', knAll)
    + fbtn('all','全部', all.length)
    + '<span class="gh-f'+(GH_VIEW==='line'?' on':'')+'" data-view="line" role="button" tabindex="0">名条</span>'
    + '<span class="gh-f'+(GH_VIEW==='card'?' on':'')+'" data-view="card" role="button" tabindex="0">详卡</span>'
    + '</div>';
  bar += '<div class="gh-fs" style="margin-top:-4px">'
    + ['游魂','怨煞','恶厉','红衣','罗刹','鬼王'].map(function(k){
        return '<span class="gh-f'+(GH_LV===k?' on':'')+'" data-lv="'+k+'" role="button" tabindex="0">'+k+'</span>';
      }).join('')
    + '<input class="gh-q" id="ghQ" type="text" placeholder="搜落点 / 已探知名讳" value="'+esc(GH_Q)+'" maxlength="24">'
    + '</div>';
  g = page;
  if(!all.length){
    s='<div class="bh-empty">当前尚无在册鬼口 · 查案、遇异或听闻传闻后将在此记档</div>';
  }else if(!view.length){
    s='<div class="bh-empty">这一档筛不出鬼 · 换个阶位或清空关键词试试</div>';
  }else{
    s=g.slice().sort(function(a,b){return (Number(b.s)||0)-(Number(a.s)||0);}).map(function(x){
      var n=String(x.n||'').trim(), st=Number(x.s)||0, k=String(x.k||'未知').trim();
      var lv = ghLvName(x);
      var col = st>=800?'#D9432F':st>=600?'#C4553C':st>=400?'#C89B3C':'#8C6A2A';
      var isUnk = ghIsUnk;
      var rawR = String(x.r||'').trim(), rawW = String(x.w||'').trim();
      var known = ghIsKnown(x);
      var hasName = !isUnk(n);
      var nm = hasName ? esc(n) : '未名阴煞';
      var ow = String(x.owner||'');
      var owTag = ow ? ('<span style="flex:0 0 auto;font-size:9.5px;color:#6B5A46;border:1px solid #3a2f20;padding:1px 4px;border-radius:2px;margin-left:4px">'+esc(ow)+'</span>') : '';
      var rl = !isUnk(rawR) ? esc(rawR) : '（未探知）';
      var wl = !isUnk(rawW) ? esc(rawW) : '（未探知）';
      var stLab = !isUnk(rawW) ? '死穴已明' : (hasName ? '已照面 · 死穴待查' : '传闻待核');
      var _jb = String(x.job||'');
      var _gr=[["档案",stLab],["煞阶",lv+' '+(st||'待测')]]
        .concat(_jb?[["身份",_jb]]:[])
        .concat([["杀人规则",rl],["死角",wl],["落点",String(x.p||'—')+" ｜ "+String(x.t||'')],["所属",ow||"无主 · 可度化"]]);
      var _gTarget = hasName ? ('「'+n+'」') : ('在「'+String(x.p||'此处')+'」作祟的鬼口');
      var _gAct = '针对'+_gTarget+'，我决定前去查探或应对：';
      var gImg=(hasName && typeof avatarFor==='function')?(avatarFor(n)||''):'';
      var gFull=(hasName && typeof portraitFor==='function')?(portraitFor(n)||''):'';
      if(GH_VIEW==='line'){
        var _pa = String(x.p||'').split('·');
        var _tail = _pa.length>=2 ? _pa[1] : (_pa[0]||'');
        var _dotOrAva = gImg
          ? ('<img src="'+esc(gImg)+'" style="flex:0 0 18px;width:18px;height:18px;border-radius:50%;object-fit:cover;object-position:top center;border:1px solid '+col+'" alt="">')
          : ('<span class="gl-d" style="background:'+col+'"></span>');
        return '<div class="bh-gt-line" data-det="'+encodeURIComponent(nm)+'" data-rows="'+encodeURIComponent(JSON.stringify(_gr))+'" data-act="'+esc(_gAct)+'" data-act-label="前去查探 · 写草稿 ▸"'+(gFull?(' data-img="'+esc(gFull)+'"'):'')+' role="button" tabindex="0">'
          +_dotOrAva
          +'<span class="gl-n'+(ow?' ow':'')+'">'+nm+owTag+'</span>'
          +'<span class="gl-p">'+esc(_tail)+'</span>'
          +'<span class="gl-s" style="color:'+col+'">'+lv+' '+st+'</span>'
          +'</div>';
      }
      var gThumb=gImg?('<div style="flex:0 0 38px;height:48px;border-radius:2px;overflow:hidden;border:1px solid rgba(216,180,90,.28);background:#EFE6D5;flex-shrink:0"><img src="'+esc(gImg)+'" style="width:100%;height:100%;object-fit:cover;object-position:top center" alt="'+esc(nm)+'"></div>'):'';
            return '<div class="bh-gt-card" data-det="'+encodeURIComponent(nm)+'" data-rows="'+encodeURIComponent(JSON.stringify(_gr))+'" data-act="'+esc(_gAct)+'" data-act-label="前去查探 · 写草稿 ▸"'+(gFull?(' data-img="'+esc(gFull)+'"'):'')+' role="button" tabindex="0" style="margin:0 11px 6px;padding:8px 10px;background:rgba(255,255,255,.03);border-left:2px solid '+col+';border-radius:2px">'
        +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:3px">'+gThumb+'</div><div style="display:flex;align-items:baseline;gap:6px;margin-bottom:3px">'
        +'<span style="flex:1;min-width:0;font:800 13.5px/1.3 STKaiti,KaiTi,serif;color:'+(ow?'#7C7060':'#DCD0B8')+';overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+nm+owTag+'</span>'
        +'<span style="flex:0 0 auto;font:700 10.5px/1 ui-monospace,monospace;color:'+col+'">'+lv+' '+st+'</span></div>'
        +'<div style="font-size:11.5px;line-height:1.62;color:#5E4F3E">规　'+rl+'</div>'
        +'<div style="font-size:11.5px;line-height:1.62;color:#5E4F3E">忌　'+wl+'</div>'
        +'<div style="font-size:11px;color:#6B5A46;margin-top:2px">'+esc(String(x.p||''))+' ｜ '+esc(String(x.t||''))+'</div>'
        +'</div>';
    }).join('');
  }
  /* 分页尾巴 */
  if(total > GH_SHOWN){
    s += '<div class="gh-more" id="ghMore" role="button" tabindex="0">'
       + '还有 ' + (total - GH_SHOWN) + ' 只 · 再列 ' + GH_PAGE + ' 只 ▾</div>';
  }
  box.innerHTML = bar + s;
  var fs=document.getElementById('ghFs');
  if(fs){
    fs.querySelectorAll('.gh-f').forEach(function(el){
      el.addEventListener('click', function(){ ghSetFilter(el.getAttribute('data-f')); });
    });
  }
  box.querySelectorAll('[data-view]').forEach(function(el){
    el.addEventListener('click', function(){ ghSetView(el.getAttribute('data-view')); });
  });
  box.querySelectorAll('[data-lv]').forEach(function(el){
    el.addEventListener('click', function(){ ghSetLv(el.getAttribute('data-lv')); });
  });
  var _qi = document.getElementById('ghQ');
  if(_qi){
    _qi.addEventListener('input', function(){ ghSetQ(_qi.value); });
  }
  var gm=document.getElementById('ghMore');
  if(gm){
    gm.addEventListener('click', function(){
      GH_SHOWN += GH_PAGE;
      var sc = box.parentNode ? box.parentNode.scrollTop : 0;
      renderGhost();
    });
  }
  var c=document.getElementById('ghCnt');
  if(c){ var kn=all.filter(ghIsKnown).length;
    c.textContent = all.length? ('在册 '+all.length+' · 已知 '+kn
      + (total!==all.length ? ' · 本屏 '+total : '')) : '空'; }

  /* 世界动向 */
  var wb=document.getElementById('ghWorld');
  if(wb){
    var w=(V.world||[])[0]||{};
    var ws='';
    var cityLevels=(w.city && typeof w.city==='object' && !Array.isArray(w.city))?w.city:{};
    if(Object.keys(cityLevels).length){
      ws+='<div style="margin:0 11px 6px;display:flex;flex-wrap:wrap;gap:4px">';
      for(var kk in cityLevels){
        var v=Number(cityLevels[kk])||0, cc=v>=80?'#D9432F':v>=55?'#C89B3C':'#7C8F6B';
        ws+='<span style="padding:2px 7px;border-radius:2px;font-size:10.5px;background:rgba(255,255,255,.04);border:1px solid '+cc+'55;color:'+cc+'">'+esc(kk)+' '+v+'</span>';
      }
      ws+='</div>';
    }
    if(w.tj!==undefined) ws+='<div style="margin:0 11px 5px;font-size:11.5px;color:#5E4F3E">特调局掌握度　<b style="color:'+(Number(w.tj)>=60?'#D9432F':'#C2B49B')+'">'+w.tj+'</b> / 100</div>';
    if(w.price) ws+='<div style="margin:0 11px 5px;font-size:11.5px;color:#5E4F3E">阴市　'+esc(String(w.price))+'</div>';
    if(w.month || w['月']) ws+='<div style="margin:0 11px 5px;font-size:11px;color:#6B5A46">'+esc(String(w.month || w['月']))+'</div>';
    wb.innerHTML = ws || '<div class="bh-empty">世界尚未结算</div>';
  }

  /* 地盘归属 */
  var pb=document.getElementById('ghPlace');
  if(pb){
    var pl=V.place||[], ps='';
    if(!pl.length){ ps='<div class="bh-empty">舆图未登记</div>'; }
    else{
      var ORD={'复绿':-1,'自家':0,'他占':1,'真空':2,'未定':3,'无主':4};
      pl=pl.slice().sort(function(a,b){ return (ORD[a.o]===undefined?9:ORD[a.o])-(ORD[b.o]===undefined?9:ORD[b.o]); });
      ps=pl.slice(0,14).map(function(x){
        var o=String(x.o||'').trim();
        if(/逢阴阁/.test(String(x.n||'')) && (!o || o==='无主')) o='自家';
        if(!o){ o = '未定'; }
        var cc = o==='复绿'?'#3E8E5A': o==='自家'?'#C89B3C': o==='他占'?'#C4553C': o==='真空'?'#8B5FA8': o==='未定'?'#6E7A6A':'#94856A';
        var dot = o==='复绿' ? '✦' : o==='真空' ? '◈' : o==='自家' ? '◆' : o==='他占' ? '◇' : '○';
        var dd=Number(x.d)||0, stars='';
        for(var si=0;si<dd;si++) stars+='★';
        var _pr=[["归属",o+(x.by?(' · '+x.by):'')],["危险",stars||'—'],["驻鬼",String(x.g||'无')],["变动",String(x.t||'—')]];
        return '<div data-det="'+encodeURIComponent(String(x.n||''))+'" data-rows="'+encodeURIComponent(JSON.stringify(_pr))+'" data-act="'+esc('我动身前往「'+String(x.n||'')+'」察看现场：')+'" data-act-label="前往此处 · 写草稿 ▸" role="button" tabindex="0" style="margin:0 11px 4px;display:flex;gap:6px;align-items:baseline">'
          +'<span style="flex:0 0 auto;font-size:11px;color:'+cc+'">'+dot+'</span>'
          +'<span style="flex:1;min-width:0;font-size:12px;color:#3A2F24;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(String(x.n||''))+'</span>'
          +'<span style="flex:0 0 auto;font-size:10px;color:'+cc+'">'+(x.by?esc(String(x.by)):o)+'</span>'
          +'</div>';
      }).join('');
      var cnt={}; pl.forEach(function(z){
        var o=String(z.o||'').trim();
        if(/逢阴阁/.test(String(z.n||'')) && (!o || o==='无主')) o='自家';
        if(!o){ o = '未定'; }
        cnt[o]=(cnt[o]||0)+1;
      });
      var _rv=Number(V.recover)||0;
      var _bar='<div style="margin:0 11px 6px">'
        +'<div style="display:flex;justify-content:space-between;font-size:11px;color:#6B5A46">'        +'<span>复 绿 进 度</span><span style="color:'+(_rv>=99?'#3E8E5A':'#C2B49B')+'">'+_rv+'%</span></div>'
        +'<div style="margin-top:3px;height:3px;background:#DFD3BE;border-radius:2px;overflow:hidden">'        +'<div style="height:100%;width:'+_rv+'%;background:linear-gradient(90deg,#2E6B44,#3E8E5A)"></div></div></div>';
      ps=_bar+'<div style="margin:0 11px 5px;font-size:11px;color:#6B5A46">复绿 '+(cnt['复绿']||0)+' ｜ 自家 '+(cnt['自家']||0)+' ｜ 他占 '+(cnt['他占']||0)+' ｜ 真空 '+(cnt['真空']||0)+' ｜ 未定 '+(cnt['未定']||0)+'</div>'+ps;
    }
    pb.innerHTML=ps;
  }

  /* 待办线头 */
  var hb=document.getElementById('ghHook');
  if(hb){
    var h=V.hook||[], hs='';
    if(!h.length){ hs='<div class="bh-empty">无线头</div>'; }
    else{
      hs=h.map(function(x){
        var dd=Number(x.d)||0, cc= dd<=2?'#D9432F':dd<=5?'#C89B3C':'#8C6A2A';
        var _hr=[['剩余',dd+' 轮'],['线索',String(x.n||'—')],['到期后果',String(x.x||'待核')]];
        return '<div data-det="'+encodeURIComponent('线头 · '+String(x.n||''))+'" data-rows="'+encodeURIComponent(JSON.stringify(_hr))+'" data-act="'+esc('围绕待办线头「'+String(x.n||'')+'」，我决定：')+'" data-act-label="介入此线 · 写草稿 ▸" role="button" tabindex="0" style="margin:0 11px 5px;display:flex;gap:7px;align-items:baseline;cursor:pointer">'
          +'<span style="flex:0 0 26px;font:800 11px/1 ui-monospace,monospace;color:'+cc+'">'+dd+'轮</span>'
          +'<span style="flex:1;min-width:0;font-size:12px;color:#3A2F24">'+esc(String(x.n||''))+'<i style="display:block;font-style:normal;font-size:10.5px;color:#6B5A46">'+esc(String(x.x||''))+'</i></span>'
          +'</div>';
      }).join('');
    }
    hb.innerHTML=hs;
  }

  var t=document.getElementById('ghTip');
  if(t){
    var over=(V.hook||[]).filter(function(x){return (Number(x.d)||0)<=2;}).length;
    if(over) t.textContent='有 '+over+' 条线头临近期限，具体后果请查对应事项。';
    else t.textContent='';
  }
  return 0;
}

function renderW5(){
  var host=document.getElementById('ftW5'); if(!host)return;
  var dims=[
    ['ti','体魄','体能、负重、抗震与气血恢复','我专心锤炼体魄筋骨（操练、行桩、药浴或合修蕴养）：'],
    ['dan','胆气','直面凶煞与高压下的沉稳决断','我磨砺胆气定力（夜探险地或静心守神）：'],
    ['jian','见识','辨伪、民俗掌眼、查档与识破死穴','我翻阅旧档典籍、访人长进见识与掌眼功夫：'],
    ['shou','手艺','画符、修器、勘验与施术准度','我静下心磨炼手艺（练笔画符、打磨法器或演练术式）：'],
    ['fu','福缘','善果机缘、险中逢生与因果气运','我出门走动积攒善缘或察看近来机缘流向：']
  ];
  host.innerHTML='<div class="ft-sub">五 维 修 炼（上 不 封 顶）</div>'+dims.map(function(d){
    var raw=Number(V.pact[d[0]]);
    if(!isFinite(raw)||raw<0) raw=0;
    /* 上不封顶：超过 100 自动扩尺并标「破限」，不再当旧档待迁移 */
    var cap = raw>100 ? Math.ceil(raw/100)*100 : 100;
    var n = Math.max(0, Math.min(100, Math.round(raw/cap*100)));
    var btag = raw>100 ? '<span style="color:#C89B3C;font-size:9px;letter-spacing:.08em;margin-left:4px">破限</span>' : '';
    var drows = [['维度',d[1]+'（当前 '+Math.floor(raw)+'）'],['作用',d[2]],['怎么涨','日常专练/实案实践每次+1~3，洗髓/合修/破大案+3~10；跨日历练按天数累加，超过100自动破限不设上限']];
    return '<div class="ft-r" role="button" tabindex="0" data-det="'+d[1]+'" data-rows="'+encodeURIComponent(JSON.stringify(drows))+'" data-act="'+esc(d[3])+'" data-act-label="专练'+d[1]+' ▸"><span class="ft-k">'+d[1]+'</span>'
      + '<span class="ft-b"><i style="width:'+n+'%;background:'+(raw>100?'#C89B3C':'#8C6A2A')+'"></i></span>'
      + '<b class="ft-v">'+Math.floor(raw)+'</b></div>'
      + '<div class="ft-note">'+d[2]+btag+'</div>';
  }).join('');
}

/* 命契三戒：契条列表。展开态记在 OATH_OPEN，重渲染不丢。 */
var OATH_OPEN={};
var OATH_KN=['一','二','三','四','五','六'];
function renderOaths(){
 var host=document.getElementById('pcOaths'),raw=document.getElementById('v-oathRaw');if(!host)return;
 var o;try{o=(window.__bhDemo&&window.__bhDemo.oath)?window.__bhDemo.oath:JSON.parse(raw?raw.value:'');}catch(e){}
 if(!o||o.version!==1||!Array.isArray(o.selected)){
   host.innerHTML='<div class="bh-empty" style="margin:0 11px">命誓状态待核，不从旧戒推断新誓。</div>';return;
 }
 if(!o.selected.length){
   host.innerHTML='<div class="bh-empty" style="margin:0 11px">三誓未落定</div>';return;
 }
 host.innerHTML=o.selected.map(function(x,i){
   var st=String(x.state||x.status||'待核');
   var cls=/守誓|已立|成立/.test(st)?' ok':(/破誓|已破|失效/.test(st)?' bad':'');
   var on=!!OATH_OPEN[i];
   var rows=[['所系',x.target||'尚未确认'],['约束',x.boundary],['不计破戒',x.exceptions],['重罚',x.penalty],['修复',x.repair]];
   var body=rows.filter(function(r){return String(r[1]==null?'':r[1]).trim();}).map(function(r){
     return '<div class="pc-oath-i"><b>'+r[0]+'</b><span>'+esc(String(r[1]))+'</span></div>';
   }).join('');
   return '<div class="pc-oath'+(on?' on':'')+'" data-oath="'+i+'" role="button" tabindex="0">'
     + '<div class="pc-oath-h">'
     + '<span class="pc-oath-k">戒'+(OATH_KN[i]||(i+1))+'</span>'
     + '<span class="pc-oath-n">'+esc(x.category)+' · '+esc(x.name)+'</span>'
     + '<span class="pc-oath-s'+cls+'">'+esc(st)+'</span>'
     + '<span class="pc-oath-x">'+(on?'收':'详')+'</span>'
     + '</div>'
     + '<div class="pc-oath-b">'+body+'</div>'
     + '</div>';
 }).join('');
 if(!host.__oathBound){
   host.__oathBound=true;
   host.addEventListener('click',function(e){
     var t=e.target.closest?e.target.closest('[data-oath]'):null; if(!t) return;
     var i=t.getAttribute('data-oath'); OATH_OPEN[i]=!OATH_OPEN[i];
     try{ renderOaths(); }catch(err){}
   });
   host.addEventListener('keydown',function(e){
     if(e.key!=='Enter'&&e.key!==' ') return;
     var t=e.target.closest?e.target.closest('[data-oath]'):null; if(!t) return;
     e.preventDefault();
     var i=t.getAttribute('data-oath'); OATH_OPEN[i]=!OATH_OPEN[i];
     try{ renderOaths(); }catch(err){}
   });
 }
 var box=document.getElementById('pcVow');if(box&&o.locked)box.style.display='none';else if(box)box.style.display='';
}
