var CASE_OPEN_T=false, CASE_OPEN_R=false;
/* 抉择页草稿：QPICK=选项拼出的行，DRAFT=用户手打或改写的部分 */
var DRAFT='';
var LOG_OPEN={};
function bhTaskDraft(x){
  var n=String((x&&(x.n||x.name))||''), s=String((x&&(x.s||x.state))||'可接');
  var g=String((x&&(x.g||x.goal))||'');
  if(/进行|在办/.test(s)){
    return '针对正在进行的「'+n+'」'+(g?'（'+g+'）':'')+'，我决定：';
  }
  return '我准备接下委托「'+n+'」'+(g?'，先从「'+g+'」入手：':'：');
}
function bhOpenTaskDet(idx){
  var TK=V.task||[], x=TK[idx];
  if(!x) return false;
  var n=String((x&&(x.n||x.name))||'未名卷宗'), s=String((x&&(x.s||x.state))||'可接');
  var g=String((x&&(x.g||x.goal))||'待查明'), rw=String((x&&(x.r||x.reward))||'未知');
  var done=/完成|已了|失败|破局/.test(s);
  var rawKws=(n+' '+g).split(/[·\s—\-，,。：:与和的之（）()「」]+/).filter(function(w){ return w && w.length>=2; });
  var kws=[];
  rawKws.forEach(function(w){
    if(kws.indexOf(w)<0) kws.push(w);
    if(w.length>=4){
      var p2=w.slice(0,2);
      if(kws.indexOf(p2)<0 && !/^(应对|处理|查清|调查|前往|继续|目前|当前)$/.test(p2)) kws.push(p2);
    }
  });
  var hit=function(str){
    var txt=String(str||'');
    if(!txt) return false;
    return kws.some(function(w){ return txt.indexOf(w)>=0; });
  };
  var relRum=(V.rumor||[]).filter(function(r){ return hit((r.t||'')+' '+(r.p||'')+' '+(r.d||'')); }).map(function(r){ return String(r.t||'')+(r.d?('：'+r.d):''); });
  var relGh=(V.ghost||[]).filter(function(gh){ return hit((gh.n||'')+' '+(gh.p||'')+' '+(gh.owner||'')); }).map(function(gh){ return (!ghIsUnk(gh.n)?String(gh.n||''):'未名阴煞')+'（'+(typeof ghLvName==='function'?ghLvName(gh):'')+' · '+String(gh.p||'—')+'）'; });
  var relEmg=(V.emg||[]).filter(function(em){ return hit((em.n||'')+' '+(em.c||'')+' '+(em.d||'')); }).map(function(em){ return String(em.n||'')+'（'+String(em.st||'未知')+'｜域规：'+String(em.g||'未知')+'）'; });
  var relLog=(V.log||[]).filter(function(lg){ return hit((lg.loc||'')+' '+(lg.who||'')+' '+(lg.ev||'')); }).slice(-3).map(function(lg){ return String(lg.t||'')+' · '+String(lg.ev||''); });
  var rows=[
    ['状态', s],
    ['目标', g],
    ['报酬', rw],
    ['相关传闻', relRum.length ? relRum.join('；') : '暂无直接关联传闻（可去「传言」页或街头打听）'],
    ['鬼口/凶域', (relGh.concat(relEmg)).length ? relGh.concat(relEmg).join('；') : '尚无直接关联登记'],
    ['已记纪事', relLog.length ? relLog.join('；') : '暂无关联纪事']
  ];
  var actTxt = done ? '' : bhTaskDraft(x);
  var actLb = /进行|在办/.test(s) ? '写入「推进此案」草稿 ▸' : '写入「接手此案」草稿 ▸';
  showDet('卷宗 · '+n, rows, '', actTxt, actLb);
  return true;
}
function bhOpenRumorDet(idx){
  var RM=V.rumor||[], x=RM[idx];
  if(!x) return false;
  var t=String((x&&(x.t||x.title))||'市井传闻'), s=String((x&&(x.s||x.src))||'未知来源');
  var p=String((x&&(x.p||x.place))||'未指明地点'), dd=String((x&&(x.d||x.desc))||'—');
  var rows=[['来源',s],['地点',p],['内容',dd]];
  var cmd='我顺着传闻「'+t+'」'+(p&&p!=='未指明地点'?('去「'+p+'」'):'')+'打探底细：';
  showDet('传闻 · '+t, rows, '', cmd, '写入「追查传闻」草稿 ▸');
  return true;
}
function renderCase(){
  var tt=document.getElementById('csTask'), rr=document.getElementById('csRumor');
  if(!tt) return 0;
  var TK=V.task, T5=CASE_OPEN_T?TK:TK.slice(0,5);
  tt.innerHTML = TK.length ? (T5.map(function(x, idx){
    var n=String((x&&(x.n||x.name))||''), s=String((x&&(x.s||x.state))||'可接');
    var g=String((x&&(x.g||x.goal))||''), rw=String((x&&(x.r||x.reward))||'');
    var isDone=/完成|已了/.test(s), isBad=/失败|破局/.test(s), isIng=/进行|在办/.test(s);
    var cls=isDone?'ok':(isBad?'bad':(isIng?'ing':'new'));
    var o='<div class="cs-t '+cls+'" data-task-det="'+idx+'" role="button" tabindex="0">';
    o+='<div class="cs-t-h"><span class="cs-t-n">'+esc(n)+'</span><span class="cs-t-s">'+esc(s)+'</span></div>';
    if(g) o+='<div class="cs-t-g">目标：'+esc(g)+'</div>';
    if(rw) o+='<div class="cs-t-r">报酬：'+esc(rw)+'</div>';
    if(isDone || isBad){
      o+='<div class="bh-case-actions"><button type="button" class="bh-action sec" data-task-det="'+idx+'">查阅归档</button></div>';
    }else if(isIng){
      o+='<div class="bh-case-actions"><button type="button" class="bh-action sec" data-task-det="'+idx+'">查阅卷宗</button><button type="button" class="bh-action pri" data-task-act="'+idx+'">推进此案 ›</button></div>';
    }else{
      o+='<div class="bh-case-actions"><button type="button" class="bh-action sec" data-task-det="'+idx+'">查阅卷宗</button><button type="button" class="bh-action pri" data-task-act="'+idx+'">接下委托 ›</button></div>';
    }
    return o+'</div>';
  }).join('') + (TK.length>5 ? ('<div class="gh-more" id="csTMore" role="button" tabindex="0">'
      + (CASE_OPEN_T?('收起 · 只留 5 桩 ▴'):('还有 '+(TK.length-5)+' 桩 · 展开 ▾')) + '</div>') : ''))
  : '<div class="bh-empty">案上无卷 · 待你接下第一桩</div>';
  var _tm=document.getElementById('csTMore');
  if(_tm) _tm.addEventListener('click', function(){ CASE_OPEN_T=!CASE_OPEN_T; try{ renderCase(); }catch(e){} });
  if(!tt.__caseBound){
    tt.__caseBound=true;
    tt.addEventListener('click',function(ev){
      var act=ev.target&&ev.target.closest?ev.target.closest('[data-task-act]'):null;
      if(act){
        ev.preventDefault(); ev.stopPropagation();
        var i=Number(act.getAttribute('data-task-act'));
        var x=(V.task||[])[i];
        if(x){
          var cmd = bhTaskDraft(x).replace(/[：:]\s*$/, '，先探明眼下这一步。');
          if(typeof bhSend==='function') bhSend(cmd);
          else if(typeof bhAct==='function') bhAct(cmd);
        }
        return;
      }
      var det=ev.target&&ev.target.closest?ev.target.closest('[data-task-det]'):null;
      if(det){
        ev.preventDefault(); ev.stopPropagation();
        bhOpenTaskDet(Number(det.getAttribute('data-task-det')));
      }
    });
  }
  var RM=V.rumor, R4=CASE_OPEN_R?RM:RM.slice(0,4);
  rr.innerHTML = RM.length ? (R4.map(function(x, idx){
    var t=String((x&&(x.t||x.title))||''), s=String((x&&(x.s||x.src))||'');
    var p=String((x&&(x.p||x.place))||''), dd=String((x&&(x.d||x.desc))||'');
    var o='<div class="cs-r" data-rumor-det="'+idx+'" role="button" tabindex="0">';
    o+='<div class="cs-r-t">'+esc(t)+'</div>';
    if(s||p) o+='<div class="cs-r-m">'+esc([s,p].filter(Boolean).join(' · '))+'</div>';
    if(dd) o+='<div class="cs-r-d">'+esc(dd)+'</div>';
    o+='<div class="bh-case-actions"><button type="button" class="bh-action" data-rumor-act="'+idx+'">追查此事 ›</button></div>';
    return o+'</div>';
  }).join('') + (RM.length>4 ? ('<div class="gh-more" id="csRMore" role="button" tabindex="0">'
      + (CASE_OPEN_R?('收起 · 只留 4 条 ▴'):('还有 '+(RM.length-4)+' 条 · 展开 ▾')) + '</div>') : ''))
  : '<div class="bh-empty">茶楼里还没人说起怪事</div>';
  var _rm=document.getElementById('csRMore');
  if(_rm) _rm.addEventListener('click', function(){ CASE_OPEN_R=!CASE_OPEN_R; try{ renderCase(); }catch(e){} });
  if(rr && !rr.__rumorBound){
    rr.__rumorBound=true;
    rr.addEventListener('click',function(ev){
      var act=ev.target&&ev.target.closest?ev.target.closest('[data-rumor-act]'):null;
      if(act){
        ev.preventDefault(); ev.stopPropagation();
        var i=Number(act.getAttribute('data-rumor-act'));
        var x=(V.rumor||[])[i];
        if(x){
          var t=String((x&&(x.t||x.title))||''), p=String((x&&(x.p||x.place))||'');
          var rcmd='我顺着传闻「'+t+'」'+(p?('去「'+p+'」'):'')+'打探底细。';
          if(typeof bhSend==='function') bhSend(rcmd);
          else if(typeof bhAct==='function') bhAct(rcmd);
        }
        return;
      }
      var det=ev.target&&ev.target.closest?ev.target.closest('[data-rumor-det]'):null;
      if(det){
        ev.preventDefault(); ev.stopPropagation();
        bhOpenRumorDet(Number(det.getAttribute('data-rumor-det')));
      }
    });
  }
  var c=document.getElementById('csCnt');
  if(c) c.textContent = '案 ' + V.task.length + ' · 闻 ' + V.rumor.length;
  return V.task.length;
}
/* ---------- 一日志：按天分节，时间｜地点｜谁｜做了什么 ---------- */
function normLog(x){
  if(!x) return null;
  if(typeof x === 'string') return { d:'', t:'', loc:'', who:'', ev:x };
  var dd = x.d, day = '', desc = '';
  if(typeof dd === 'number') day = dd;
  else if(/^\d{1,4}$/.test(String(dd === undefined ? '' : dd))) day = Number(dd);
  else if(dd) desc = String(dd);
  return {
    d: (x.day !== undefined ? x.day : day),
    t: String(x.t || x.time || ''),
    loc: String(x.loc || x.p || ''),
    who: String(x.who || x.w || ''),
    ev: String(x.ev || x.e || x.txt || desc || '')
  };
}
function renderLog(){
  var box = document.getElementById('bhLogPanel');
  if(!box) return;
  var items = (V.log || []).map(normLog).filter(function(x){ return x && (x.ev || x.t); });
  var byDay = {}, order = [];
  items.forEach(function(x){
    var key = (x.d === '' || x.d === undefined) ? '—' : String(x.d);
    if(!byDay[key]){ byDay[key] = []; order.push(key); }
    byDay[key].push(x);
  });
  order.sort(function(a, b){
    var na = (a === '—') ? -1 : (Number(a) || 0), nb = (b === '—') ? -1 : (Number(b) || 0);
    return nb - na;
  });
  var html = '';
  order.forEach(function(key,index){
    /* 不再用原生 <details>/<summary>：那个三角是浏览器自带的，跟本卡视觉语言冲突。
       改成「日期脊条 + 朱砂标记」的契条式折叠，展开态记在 LOG_OPEN 里。 */
    var _open = LOG_OPEN[key] || (index===0 && LOG_OPEN.__init!==true);
    html += '<div class="lg-day'+(index===0?' first':'')+(_open?' on':'')+'" data-log="'+esc(String(key))+'">'
      + '<div class="lg-day-h"><i class="lg-day-dot"></i>'
      + '<span class="lg-day-n">'+(key==='—'?'未记日':'第 '+(Number(key)+1)+' 日')+'</span>'
      + '<span class="lg-day-m">'+byDay[key].length+' 条</span>'
      + '<em class="lg-day-x">'+( _open?'收':'展' )+'</em></div>'
      + '<div class="lg-day-b">';
    byDay[key].forEach(function(x){
      html += '<div class="lg-row">'
        + (x.t ? '<span class="lg-t">' + esc(x.t) + '</span>' : '')
        + (x.loc ? '<span class="lg-l">' + esc(x.loc) + '</span>' : '')
        + (x.who ? '<span class="lg-w">' + esc(x.who) + '</span>' : '')
        + '<span class="lg-e">' + esc(x.ev) + '</span></div>';
    });
    html+='</div></div>';
  });
  if(!html) html = '<div class="bh-empty">尚无一日志 · 有实质事件才会落笔</div>';
  box.innerHTML = '<div class="lg-hd"><span>一日志</span><span class="lg-sub">时间｜地点｜谁｜做了什么</span></div>' + html;
  if(!box.__logBound){
    box.__logBound = true;
    box.addEventListener('click', function(e){
      var h=e.target.closest?e.target.closest('[data-log]'):null; if(!h) return;
      var k=h.getAttribute('data-log');
      LOG_OPEN[k]=!LOG_OPEN[k]; LOG_OPEN.__init=true;   /* 用户碰过就不再自动展开第一天 */
      try{ renderLog(); }catch(err){}
    });
  }
}

/* ===== 欠与托：债条 / 冥条 / 线头条 =====
   数据：V.debt（数）与 V.debtList（明细，{w:债主,t:欠什么,d:剩余日}）
         V.yinzhai 与 V.yinzhaiList；V.hook=[{d,n,x}]
   明细为空而数值非零时，只出数值条并提示「明细待记」，不编造债主。 */
function debtBar(v,max,bad){
  v=Number(v)||0; max=Number(max)||1000;
  var p=Math.max(0,Math.min(100,Math.round(v/max*100)));
  var hot = bad && p>=60;
  var col = hot ? '#D9432F' : (p>=80?'#C89B3C':'#8C6A2A');
  return '<span class="pc-ow-b"><i style="width:'+p+'%;background:'+col+'"></i></span>';
}
function debtBlock(tag,val,list,label,emptyTxt){
  var v=Number(val)||0, L=Array.isArray(list)?list:[];
  if(!v && !L.length) return '';
  var h='<div class="pc-ow">'
    + '<div class="pc-ow-h">'
    + '<span class="pc-ow-k">'+tag+'</span>'
    + '<span class="pc-ow-n">'+label+'</span>'
    + debtBar(v,1000,tag==='债'?false:true)
    + '<span class="pc-ow-v">'+v+'</span>'
    + '</div>';
  if(L.length){
    h += L.slice(0,6).map(function(x){
      var w=String((x&&(x.w||x.n||x.who))||''), t=String((x&&(x.t||x.d||x.why))||'');
      var dd=(x&&x.d!==undefined)?Number(x.d):NaN;
      var due = isFinite(dd) ? (dd<=2?'<b class="pc-ow-due hot">余'+dd+'日</b>':(dd<=5?'<b class="pc-ow-due">余'+dd+'日</b>':'')) : '';
      return '<div class="pc-ow-i"><span class="pc-ow-w">'+esc(w||'未记债主')+'</span>'
        + '<span class="pc-ow-t">'+esc(t)+(due?'　'+due:'')+'</span></div>';
    }).join('');
    if(L.length>6) h += '<div class="pc-ow-more">另有 '+(L.length-6)+' 笔未列</div>';
  } else if(v){
    h += '<div class="pc-ow-i"><span class="pc-ow-t">明细待记：债主与事项由正文确认后补登</span></div>';
  } else {
    h += '<div class="pc-ow-i"><span class="pc-ow-t">'+emptyTxt+'</span></div>';
  }
  return h+'</div>';
}
function hookBlock(hk){
  var A=Array.isArray(hk)?hk:[];
  if(!A.length) return '';
  /* 按剩余日升序，最近的压在最上 */
  var B=A.slice(0).sort(function(a,b){ return (Number(a&&a.d)||999)-(Number(b&&b.d)||999); });
  var h='<div class="pc-ow"><div class="pc-ow-h">'
    + '<span class="pc-ow-k">期</span><span class="pc-ow-n">线头</span>'
    + '<span class="pc-ow-b" style="background:none"></span>'
    + '<span class="pc-ow-v">'+A.length+'</span></div>';
  h += B.slice(0,6).map(function(x){
    var dd=Number(x&&x.d)||0;
    var cls = dd<=2 ? ' hot' : (dd<=5 ? '' : ' far');
    return '<div class="pc-ow-i"><span class="pc-ow-due'+cls+'">'+dd+'日</span>'
      + '<span class="pc-ow-t"><b class="pc-ow-hn">'+esc(String((x&&x.n)||'线头'))+'</b>'
      + (x&&x.x?'<i class="pc-ow-x">'+esc(String(x.x))+'</i>':'')+'</span></div>';
  }).join('');
  if(A.length>6) h += '<div class="pc-ow-more">另有 '+(A.length-6)+' 条未列</div>';
  return h+'</div>';
}

function renderPact(){
  if(!document.getElementById('pcRule')) return 0;
  var _oathDetail=false;
  try{ var _or=(window.__bhDemo&&window.__bhDemo.oath)?window.__bhDemo.oath:JSON.parse((document.getElementById('v-oathRaw')||{}).value||'{}'); _oathDetail=!!(_or && Array.isArray(_or.selected) && _or.selected.length); }catch(e){}
  var _vh0=document.getElementById('pcVowHd'); if(_vh0) _vh0.style.display = _oathDetail ? 'none' : '';
  var ru=document.getElementById('pcRule'), ar=document.getElementById('pcArc'),
      re=document.getElementById('pcDebt'), ms=document.getElementById('pcMsg');
  var vo=document.getElementById('pcVow');
  if(vo){
    var _v=(V.vow||[]).filter(function(x){ return String(x||'').trim(); });
    /* 三重命誓有明细时不再重复显示「三条不许」摘要；命誓未落定才用 vow 兜底 */
    var oathDetail=false;
    try{ var _or=(window.__bhDemo&&window.__bhDemo.oath)?window.__bhDemo.oath:JSON.parse((document.getElementById('v-oathRaw')||{}).value||'{}'); oathDetail=!!(_or && Array.isArray(_or.selected) && _or.selected.length); }catch(e){}
    vo.innerHTML = oathDetail ? '' : (_v.length ? _v.map(function(x,i){
      return '<div class="cs-l" style="margin:0 11px 5px;display:flex;gap:7px;align-items:baseline">'
        + '<span style="flex:0 0 26px;font:700 10px/1.6 ui-monospace,monospace;color:#8E5F4C">戒'+(i+1)+'</span>'
        + '<span style="flex:1;min-width:0;font-size:12px;line-height:1.7;color:#3A2F24">'+esc(String(x))+'</span></div>';
    }).join('') : '<div style="margin:0 11px 7px;font-size:11.5px;color:#756450">命契未落定。</div>');
  }
  ru.innerHTML = V.rule.length ? V.rule.map(function(x){
    var n=String((x&&(x.n||x.name))||''), lv=String((x&&(x.lv||x.rank))||'');
    var a=String((x&&(x.a||x.r1))||''), b=String((x&&(x.b||x.r2))||''), c=String((x&&(x.c||x.live))||'');
    var o='<div class="pc-r"><div class="pc-r-h"><span class="pc-r-n">'+esc(n)+'</span>';
    if(lv) o+='<span class="pc-r-lv">'+esc(lv)+'</span>';
    o+='</div>';
    if(a) o+='<div class="pc-r-i"><b>规则一</b><span>'+esc(a)+'</span></div>';
    if(b) o+='<div class="pc-r-i"><b>规则二</b><span>'+esc(b)+'</span></div>';
    if(c) o+='<div class="pc-r-i live"><b>生路</b><span>'+esc(c)+'</span></div>';
    return o+'</div>';
  }).join('') : '<div class="bh-empty" style="margin:0 11px">尚在阳间地界 · 无域规加身</div>';
  ar.innerHTML = V.arc.length ? V.arc.map(function(x){
    var n=String((x&&(x.n||x.name))||''), s=String((x&&(x.s||x.stage))||'');
    var dd=String((x&&(x.d||x.desc))||''), r=Math.max(0,Math.min(100,Number((x&&(x.r||x.prog))||0)));
    var o='<div class="pc-a"><div class="pc-a-h"><span class="pc-a-n">'+esc(n)+'</span><span class="pc-a-s">'+esc(s)+'</span></div>';
    o+='<div class="pc-a-b"><i style="width:'+r+'%"></i></div>';
    if(dd) o+='<div class="pc-a-d">'+esc(dd)+'</div>';
    return o+'</div>';
  }).join('') : '<div class="bh-empty" style="margin:0 11px">当前无进行中的长线篇章</div>';
  /* 欠与托：人情债 / 阴债 / 线头。数值上头，明细在条里。 */
  if(re){
    var dl=V.debtList||[], yl=V.yinzhaiList||[], hk=V.hook||[];
    var h4='';
    h4+=debtBlock('债', V.debt, dl, '人情债', '未欠人情');
    h4+=debtBlock('冥', V.yinzhai, yl, '阴债', '冥途无挂');
    h4+=hookBlock(hk);
    re.innerHTML=h4;
  }
  ms.innerHTML = V.msg.length ? V.msg.slice(0,12).map(function(x){
    var f=String((x&&(x.f||x.from))||''), dd=String((x&&(x.d||x.txt))||''), t=String((x&&(x.t||x.time))||'');
    return '<div class="pc-m"><div class="pc-m-h"><span>'+esc(f)+'</span><span>'+esc(t)+'</span></div>'
      +'<div class="pc-m-d">'+esc(dd)+'</div></div>';
  }).join('') : '<div class="bh-empty" style="margin:0 11px">无人传讯</div>';
  var c=document.getElementById('pcCnt');
  if(c) c.textContent = '规 ' + V.rule.length + ' · 副 ' + V.arc.length + ' · 缘 ' + V.rel.length;
  return V.rel.length;
}


/* ---------- 交互 ---------- */
var root = document.getElementById('bh');
function isOpen(){ return root.classList.contains('open'); }
function toggle(open){
  var want = (open===undefined) ? !isOpen() : !!open;
  root.classList.toggle('open', want);
  try{ window.dispatchEvent(new Event('resize')); }catch(e){}
}

var _dx=document.getElementById('detX'); if(_dx) _dx.addEventListener('click',closeDet);
var _dd=document.getElementById('det'); if(_dd) _dd.addEventListener('click',function(e){
  if(e.target===_dd){ closeDet(); return; }
  var draftBtn = e.target && e.target.closest ? e.target.closest('[data-det-draft]') : null;
  if(draftBtn){
    e.preventDefault(); e.stopPropagation();
    var dcmd = draftBtn.getAttribute('data-det-draft')||'';
    closeDet();
    if(dcmd && typeof bhAct==='function') bhAct(dcmd);
    return;
  }
  var sendBtn = e.target && e.target.closest ? e.target.closest('[data-det-send],[data-det-act]') : null;
  if(sendBtn){
    e.preventDefault(); e.stopPropagation();
    var scmd = sendBtn.getAttribute('data-det-send') || sendBtn.getAttribute('data-det-act') || '';
    closeDet();
    if(scmd){
      if(typeof bhSend==='function') bhSend(scmd);
      else if(typeof bhAct==='function') bhAct(scmd);
    }
  }
});
/* ===== v24 · 分页：页签切卷 + 卷首注入 ===== */
(function(){
  var pnl = document.getElementById('pnl'); if(!pnl) return;
  var tabs = document.getElementById('tabs');
  var pgs = [].slice.call(pnl.querySelectorAll('.bh-pg'));

  /* 卷首注入 */
  pgs.forEach(function(p, i){
    if(p.querySelector('.bh-sec')) return;
    var num = ('0' + (i+1)).slice(-2);
    var dv = document.createElement('div');
    dv.className = 'bh-sec';
    dv.innerHTML = '<span class="bh-sec-n">' + (p.getAttribute('data-sec') || '') + '</span>'
                 + '<span class="bh-sec-s">' + (p.getAttribute('data-sub') || '') + '</span>'
                 + '<span class="bh-sec-i">' + num + '</span>';
    p.insertBefore(dv, p.firstChild);
  });

  if(!tabs) return;
  var tabEls = [].slice.call(tabs.querySelectorAll('.bh-tab'));
  function show(n){
    tabEls.forEach(function(x){ x.classList.toggle('on', x.getAttribute('data-p') === n); });
    pgs.forEach(function(p){ p.classList.toggle('on', p.id === ('pg-' + n)); });
    if(n === 'map'){ try{ if(window.bhMapFollow && !window.__bhUserMovedMap) window.bhMapFollow(); }catch(e){} }
    try{ window.parent && window.parent.postMessage({type:'bh-resize'}, '*'); }catch(e){}
  }
  tabs.addEventListener('click', function(e){
    var t = e.target.closest ? e.target.closest('.bh-tab') : null;
    if(!t) return;
    show(t.getAttribute('data-p'));
  });
  if(!pnl.querySelector('.bh-pg.on')) show('map');
  else { var cur = pnl.querySelector('.bh-pg.on'); show(cur.id.replace('pg-','')); }
})();


/* ---------- 鬼名生成：姓 × 名 × 号，组合出数千个不重名的鬼 ---------- */
var GSUR = ['王','李','张','刘','陈','杨','赵','黄','周','吴','徐','孙','胡','朱','高','林','何','郭','马','罗',
  '梁','宋','郑','谢','韩','唐','冯','于','董','萧','程','曹','袁','邓','许','傅','沈','曾','彭','吕',
  '苏','卢','蒋','蔡','贾','丁','魏','薛','叶','阎','余','潘','杜','戴','夏','钟','汪','田','任','姜',
  '范','方','石','姚','谭','廖','邹','熊','金','陆','郝','孔','白','崔','康','毛','邱','秦','江','史',
  '顾','侯','邵','孟','龙','万','段','章','钱','汤','尹','黎','易','常','武','乔','贺','赖','龚','文'];
var GMIN = ['未晞','见山','兰','漾','砚秋','春信','无咎','红药','雪见','三眠','青梧','昭昭','玉笙','晚棠','幽璃',
  '浅雪','桂仙','冷竹','清瓷','青裴','幼薇','燕拂衣','罗浮生','小萼','素问','青鸾','康宁','红笺','三娘','霜',
  '知月','银枝','枝','小满','怜','阿依','关雪','小蝉','玉','谷雨','简宁','辛夷','言秋','云岫','阿茶','慕安',
  '青山','必安','铁山','玉书','静姝','流萤','半夏','停云','怀瑾','折枝','听雨','望舒','采薇','扶苏','清欢',
  '南枝','素心','孤舟','寒山','远岫','秋白','长庚','无衣','有客','既白','将离','未名','不归','忘川'];
/* 号只跟"名"走，不跟姓走：要么「姓+名」要么「阿/小/老 + 名 + 称谓」，
   避免出现「谢未名郎」「刘见山太婆」这种错配。 */
/* 空串权重高，八成名号是「姓+名」这种最自然的叫法 */
var GHAO = ['','','','','','','','','','','','','','','','',
            '娘','姐','妹','姑','婆','嫂','婶','姨','伯','叔'];
/* 三个独立的线性同余步进，保证姓/名/号三维都散得开。
   之前用同一个数右移取模，高位几乎不参与 → 552 只鬼只有 97 个名字。 */
function _mkGhostName(sd){
  sd = sd >>> 0;
  var a = (Math.imul(sd ^ 0x9E3779B9, 0x85EBCA6B) >>> 0);
  var b = (Math.imul(a ^ (a >>> 13), 0xC2B2AE35) >>> 0);
  var c = (Math.imul(b ^ (b >>> 16), 0x27D4EB2F) >>> 0);
  var s = GSUR[a % GSUR.length];
  var m = GMIN[b % GMIN.length];
  var h = GHAO[c % GHAO.length];
  /* 有号时：称谓只用在「名」上（张阿婆、李嫂子），不带姓；
     没号时：走「姓+名」（张未晞）。
     另有两种常见法：老X（老周）、小X（小满）——按 c 的余数挑一种 */
  if(h){
    /* 只有两字名才适合加「阿/老」前缀；单字名一律走「姓+称谓」（张姐、李婶） */
    if(m.length >= 2 && ((c >>> 9) % 4) === 0) return '老' + m;
    return s + h;                    /* 张姐、李婶、王婆 */
  }
  return s + m;
}

