    if(!isUnstartedHost()){
      window.__bhDemo = null;
      if(bar) bar.hidden = true;
      return false;
    }
    if(bar) bar.hidden = false;
    if(on){
      window.__bhDemo = __DEMO_DATA;
      load(Object.assign({}, __DEMO_DATA));
      if(txt) txt.textContent = '◈ 广场演示预览（成都中期实况 · 落契开局后自动切回本局）';
      if(btn) btn.textContent = '看初始空档 ▸';
    } else {
      window.__bhDemo = null;
      load({
        t:g('t'), loc:g('loc'), realm:g('realm'), san:g('san'), here:g('here'),
        book:j('bookRaw'), bag:j('bagRaw'), cash:j('cashRaw'), adv:j('advRaw'),
        omen:j('omenRaw'), emg:j('emgRaw'), now:g('now'), out:j('outRaw'), radio:g('radio'), clear:j('clearRaw'),
        weather:g('weather'), phase:g('phase'), task:j('taskRaw'), rumor:j('rumorRaw'), log:j('logRaw'),
        rel:j('relRaw'), rule:j('ruleRaw'), arc:j('arcRaw'), msg:j('msgRaw'),
        ghost:j('ghostRaw'), npc:j('npcRaw'), world:j('worldRaw'), hook:j('hookRaw'),
        place:j('placeRaw'), foe:j('foeRaw'), recover:g('recover'), yinzhai:g('yinzhai'),
        power:g('power'), merit:g('merit'), life:g('life'), erode:g('erode'),
        expose:g('expose'), debt:g('debt'), spirit:g('spirit'), kcount:g('kcount'),
        repRaw:g('repRaw'), day:g('day'), others:g('others'), city:g('city'),
        worldSimRaw:g('worldSimRaw'), vow:j('vow'), pactRaw:g('pactRaw'),
        emgTurn:(function(){try{return JSON.parse(g('emgTurn')||'{}');}catch(e){return {};}})(),
        debtRaw:g('debtRaw'), yinzhaiRaw:g('yinzhaiRaw')
      });
      if(txt) txt.textContent = '◈ 当前显示：真实初始空档（待落契）';
      if(btn) btn.textContent = '看中期演示 ▸';
    }
    renderAll();
