(function(){
  if(window.__bh227ActionsBound)return;
  window.__bh227ActionsBound=true;
  var busy=false;
  function status(text){
    var el=document.getElementById('bh-action-status');
    if(!el){el=document.createElement('div');el.id='bh-action-status';el.setAttribute('role','status');(document.getElementById('pg-case')||document.getElementById('pnl')||document.body).appendChild(el);}
    el.textContent=text;
  }
  document.addEventListener('click',function(e){
    var el=e.target&&e.target.closest?e.target.closest('[data-bh-send]'):null;
    if(!el)return;
    e.preventDefault();e.stopImmediatePropagation();
    if(busy||el.disabled)return;
    var cmd=el.getAttribute('data-bh-send')||'';
    busy=true;el.disabled=true;
    try{
      var ok=typeof window.bhSend==='function'&&window.bhSend(cmd)===true;
      status(ok?'已填入聊天框':'发送失败，请用「复制」手动粘贴：'+cmd);
    }catch(err){status('发送失败，请在网站输入框手动发送：'+cmd);}
    setTimeout(function(){busy=false;el.disabled=false;},1000);
  },true);
})();
;

