/* ===== 态势阶段绑定 + 主线详情弹层 ===== */
(function(){
  var ERA_META={
    '地脉初醒':{ord:'壹/柒',bg:'300–800 处',emg:'5–10 处',world:'官方按普通刑案处理，民间零星传言',mile:'残页见名：从自身来路或街坊旧档摸到第一页除名残痕'},
    '阴潮渐起':{ord:'贰/柒',bg:'3000–8000 处',emg:'15–30 处',world:'部分街区夜禁，民间师傅四起，特调局暗中收编',mile:'三册同墨：比对旧矿井/迁镇/交接死档，查明替死借寿与人楔之账'},
    '长夜临城':{ord:'叁/柒',bg:'十万级',emg:'40–80 处',world:'特调局公开化，大城设防线、物资配给与夜禁',mile:'执笔尚在：追查当年执笔除名的掌簿支脉，找出尚在人世的两名经手人'},
    '人间如狱':{ord:'肆/柒',bg:'百万级',emg:'100–200 处',world:'多城失守、通讯中断，幸存者结聚落自保',mile:'群楔到期：六十年大限松动，查明压在你所求之人/所守之城底下的副楔'},
    '诸方举火':{ord:'伍/柒',bg:'百万级（回落）',emg:'100–200 处',world:'残存官方、道门、驻军与自救会联手反攻',mile:'拔楔或续楔：执底账与命契做出终局抉择（拔楔/续楔/改立新规）'},
    '天光一线':{ord:'陆/柒',bg:'十万级',emg:'50–100 处',world:'逐省收复复绿，清算旧账与战时代价',mile:'旧账清偿：清算借寿经手人，安置册上未散故鬼（《天光》/《长夜》）'},
    '劫后余烬':{ord:'柒/柒',bg:'万级',emg:'20–40 处',world:'尘埃落定，立下人与残存阴煞共处新规',mile:'人间留灯：定逢阴阁去留（《关门》），此后山河仍可自由行旅'}
  };
  function readMainArc(){
    try{
      if(window.V&&Array.isArray(window.V.arc)&&window.V.arc.length) return window.V.arc[0];
      var el=document.getElementById('v-arcRaw');
      var txt=el?(el.value||el.textContent||''):'';
      if(txt&&txt.indexOf('[')===0){ var a=JSON.parse(txt); if(Array.isArray(a)&&a.length) return a[0]; }
    }catch(e){}
    return null;
  }
  function paintEra(){
    var box=document.getElementById('eraBox');
    var v=document.getElementById('vEra');
    var s=document.getElementById('vEraScale');
    if(!box||!v) return;
    var raw=document.getElementById('v-era');
    var rawS=document.getElementById('v-eraScale');
    var era=(window.__bhDemo&&window.__bhDemo.era)?window.__bhDemo.era:((raw&&raw.value)?String(raw.value).trim():'地脉初醒');
    if(era.indexOf('{{')===0) era='地脉初醒';
    var scale=(window.__bhDemo&&window.__bhDemo.eraScale)?window.__bhDemo.eraScale:((rawS&&rawS.value)?String(rawS.value).trim():'');
    if(scale.indexOf('{{')===0) scale='约 500 处';
    v.textContent=era||'—';
    box.setAttribute('data-era',era);
    if(s) s.textContent=scale?('全国 '+scale):'';
    if(!box.__eraBound){
      box.__eraBound=true;
      box.title='点击查看世界态势七阶与当前主线';
      box.addEventListener('click',function(){
        var curEra=box.getAttribute('data-era')||'地脉初醒';
        var curScale=(document.getElementById('vEraScale')||{}).textContent||'';
        var m=ERA_META[curEra]||ERA_META['地脉初醒'];
        var arc=readMainArc();
        var rows=[
          ['当前阶段', curEra+'（'+m.ord+'）'],
          ['全国凶域', (curScale.replace(/^全国\s*/,'')||m.bg)+'（具名在册约 '+m.emg+'）'],
          ['世道气象', m.world],
          ['主线篇章', arc?(String(arc.n||'神州断代录')+' · '+String(arc.s||curEra)+'（'+Number(arc.r||0)+'%）'):'主线·神州断代录'],
          ['当前线头', arc&&arc.d?String(arc.d):m.mile],
          ['推进规则', '每 30 入世日保底升一阶；可随时偏离去办闲案或经营，世界自行演进']
        ];
        if(typeof window.showDet==='function') window.showDet('世界态势 · 山河主线', rows);
      });
    }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',paintEra);
  else paintEra();
  window.__bhPaintEra=paintEra;
  setInterval(paintEra, 1500);
})();
;

/* ---- module[4] ---- */
(function(){
  var BG={"map": "https://rphszy.pages.dev/file/%E5%A4%9C%E6%9C%AA%E5%A4%AE/ui%E5%BA%95%E5%BA%A7/1794287404080_RikkaHub_1794287250950.png", "cast": "https://rphszy.pages.dev/file/%E5%A4%9C%E6%9C%AA%E5%A4%AE/ui%E5%BA%95%E5%BA%A7/1794287380319_RikkaHub_1794287254928.png", "fate": "https://rphszy.pages.dev/file/%E5%A4%9C%E6%9C%AA%E5%A4%AE/ui%E5%BA%95%E5%BA%A7/1794287383772_RikkaHub_1794287260092.png", "pact": "https://rphszy.pages.dev/file/%E5%A4%9C%E6%9C%AA%E5%A4%AE/ui%E5%BA%95%E5%BA%A7/1794289807412_RikkaHub_1794289790995.png", "gear": "https://rphszy.pages.dev/file/%E5%A4%9C%E6%9C%AA%E5%A4%AE/ui%E5%BA%95%E5%BA%A7/1794287390194_RikkaHub_1794287322678.png", "case": "https://rphszy.pages.dev/file/%E5%A4%9C%E6%9C%AA%E5%A4%AE/ui%E5%BA%95%E5%BA%A7/1794287385285_RikkaHub_1794287257343.png", "opt": "https://rphszy.pages.dev/file/%E5%A4%9C%E6%9C%AA%E5%A4%AE/ui%E5%BA%95%E5%BA%A7/1794287392029_RikkaHub_1794287320394.png"};
  var BGL={"map": "data:image/jpeg;base64,", "cast": "data:image/jpeg;base64,", "fate": "data:image/jpeg;base64,", "pact": "data:image/jpeg;base64,", "gear": "data:image/jpeg;base64,", "case": "data:image/jpeg;base64,", "opt": "data:image/jpeg;base64,"};
  var CAT={book:'cast',ghost:'cast',bag:'gear',adv:'gear',opt:'opt',case:'case',world:'case'};
  function mount(){
    document.querySelectorAll('.bh-pg').forEach(function(p){
      if(p.querySelector('.page-bg')) return;
      var k=p.id.replace('pg-',''); var key=CAT[k]||k; var url=BG[key];
      if(!url) return;
      var d=document.createElement('div'); d.className='page-bg'+(k==='map'?' bg-map':'');
      d.style.backgroundImage='url("'+(BGL[key]||'')+'")';
      var im=document.createElement('img'); im.alt=''; im.decoding='async';
      im.setAttribute('data-src',url);
      im.addEventListener('load',function(){ im.classList.add('on'); });
      d.appendChild(im); p.insertBefore(d,p.firstChild);
    });
  }
  function warm(){
    document.querySelectorAll('.bh-pg.on .page-bg img[data-src]').forEach(function(i){
      i.src=i.getAttribute('data-src'); i.removeAttribute('data-src');
    });
  }
  function boot(){ mount(); warm(); }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot); else boot();
  var tabs=document.getElementById('tabs');
  if(tabs) tabs.addEventListener('click',function(){ setTimeout(warm,30); });
  setTimeout(warm,400);
})();
;

/* ---- module[5] ---- */
/* ===== 宣和内府 v3.0 · 宽屏双栏重构 + 人脉同步 + 十卷锦标角标 + 断网优雅降级 ===== */
(function(){
  function escH(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); }

  /* 0. 构建电脑宽屏双栏 DOM 容器（丝滑无损保留全部原有元素 ID 与事件监听） */
  function setupWidescreenLayouts(){
    var pnl = document.getElementById('pnl');
    if(!pnl || pnl.__v3LayoutDone) return;
    pnl.__v3LayoutDone = true;

    /* 0.1 将阴煞槽与在场条合并进并排双合通栏 .bh-top-strip */
    var sanEl = pnl.querySelector(':scope > .bh-san');
    var hereEl = pnl.querySelector(':scope > .bh-here');
    if(sanEl && hereEl && sanEl.parentNode === pnl){
      var strip = document.createElement('div');
      strip.className = 'bh-top-strip';
      pnl.insertBefore(strip, sanEl);
      strip.appendChild(sanEl);
      strip.appendChild(hereEl);
    }

    /* 0.2 第1页 #pg-map：单卷居中限宽（≤720px），不堆叠冗余右栏 */

    /* 0.3 第3页 #pg-ghost：左本省在册鬼口 + 右世界动向/地盘/线头/涌现 */
    var pgGhost = document.getElementById('pg-ghost');
    var ghList = document.getElementById('ghList');
    var ghSecH = document.getElementById('ghSecH');
    if(pgGhost && ghList && !pgGhost.querySelector('.w3-split')){
      var ghHd = pgGhost.querySelector('.bh-pg-h');
      var spG = document.createElement('div');
      spG.className = 'w3-split';
      var colGL = document.createElement('div');
      colGL.className = 'w3-pane-box';
      var colGR = document.createElement('div');
      colGR.className = 'w3-pane-box';
      Array.prototype.slice.call(pgGhost.children).forEach(function(ch){
        if(ch === ghHd) return;
        if(ch === ghSecH || ch === ghList) colGL.appendChild(ch);
        else colGR.appendChild(ch);
      });
      spG.appendChild(colGL);
      spG.appendChild(colGR);
      pgGhost.appendChild(spG);
    }

    /* 0.4 第7页 #pg-fate：四大命数卡排成 2×2 宽屏博古格 */
    var pgFate = document.getElementById('pg-fate');
    if(pgFate && !pgFate.querySelector('.w3-bento-2x2')){
      var ftCards = Array.prototype.slice.call(pgFate.querySelectorAll(':scope > .ft-card'));
      if(ftCards.length){
        var bento = document.createElement('div');
        bento.className = 'w3-bento-2x2';
        pgFate.insertBefore(bento, ftCards[0]);
        ftCards.forEach(function(c){ bento.appendChild(c); });
      }
    }

    /* 0.5 第8页 #pg-world：双栏世道态势 */
    var pgWorld = document.getElementById('pg-world');
    var wdReg = document.getElementById('wdReg');
    var wdGate = document.getElementById('wdGate');
    if(pgWorld && wdReg && !pgWorld.querySelector('.w3-split')){
      var wdHd = pgWorld.querySelector('.bh-pg-h');
      var spW = document.createElement('div');
      spW.className = 'w3-split equal';
      var colWL = document.createElement('div');
      var colWR = document.createElement('div');
      Array.prototype.slice.call(pgWorld.children).forEach(function(ch){
        if(ch === wdHd) return;
        if(ch === wdReg || ch === wdGate) colWL.appendChild(ch);
        else colWR.appendChild(ch);
      });
      spW.appendChild(colWL);
      spW.appendChild(colWR);
      pgWorld.appendChild(spW);
    }

    /* 0.6 第10页 #pg-pact：左结识人脉与域规消息 + 右立身三誓与主线债务 */
    var pgPact = document.getElementById('pg-pact');
    var pcNpc = document.getElementById('pcNpcRel');
    if(pgPact && pcNpc && !pgPact.querySelector('.w3-split')){
      var pcHd = pgPact.querySelector('.bh-pg-h');
      var spP = document.createElement('div');
      spP.className = 'w3-split equal';
      var colPL = document.createElement('div');
      colPL.className = 'w3-pane-box';
      var colPR = document.createElement('div');
      colPR.className = 'w3-pane-box';
      /* 按块归入左右栏 */
      var npcHd = pcNpc.previousElementSibling;
      var ruleEl = document.getElementById('pcRule');
      var ruleHd = ruleEl ? ruleEl.previousElementSibling : null;
      var msgEl = document.getElementById('pcMsg');
      var msgHd = msgEl ? msgEl.previousElementSibling : null;
      var leftSet = [npcHd, pcNpc, ruleHd, ruleEl, msgHd, msgEl];
      Array.prototype.slice.call(pgPact.children).forEach(function(ch){
        if(ch === pcHd) return;
        if(leftSet.indexOf(ch) >= 0) colPL.appendChild(ch);
        else colPR.appendChild(ch);
      });
      spP.appendChild(colPL);
      spP.appendChild(colPR);
      pgPact.appendChild(spP);
    }
  }

  /* 1. 精简顶栏时间格重复日期 */
  function tidyTopTimeBar(){
    var vf = document.getElementById('vFestival');
    if(!vf) return;
    var ftxt = String(vf.textContent || '').trim();
    var shortTag = ftxt.replace(/^\d{4}年\d{1,2}月\d{1,2}日\s*[·｜|]\s*/, '').trim();
    if(!shortTag || shortTag === '普通日'){
      vf.style.display = 'none';
    } else {
      vf.textContent = shortTag;
      vf.style.display = '';
    }
  }

  /* 2. 渲染「结识人物 · 异数天骄与牵绊 (npcRaw + relRaw)」 */
  function renderNpcAndRel(){
    var host = document.getElementById('pcNpcRel');
    if(!host || !window.__bhV) return;
    var V = window.__bhV;
    var merged = [], seen = {};
    (V.npc || []).forEach(function(x){
      if(!x) return;
      var n = String(x.n || x.name || '').trim();
      if(!n || seen[n]) return;
      seen[n] = {
        n: n,
        s: String(x.s || x.role || x.stage || '在册人物'),
        r: (x.r !== undefined ? x.r : (x.rel !== undefined ? x.rel : '')),
        d: String(x.d || x.desc || x.loc || x.p || '本局结识或动态涌现人物')
      };
      merged.push(seen[n]);
    });
    (V.rel || []).forEach(function(x){
      if(!x) return;
      var n = String(x.n || x.name || '').trim();
      if(!n) return;
      if(seen[n]){
        if((!seen[n].d || seen[n].d === '本局结识或动态涌现人物') && (x.d || x.desc)) seen[n].d = String(x.d || x.desc);
        if(seen[n].r === '' && x.r !== undefined) seen[n].r = x.r;
        return;
      }
      seen[n] = {
        n: n,
        s: String(x.s || x.rel || '相识'),
        r: (x.r !== undefined ? x.r : ''),
        d: String(x.d || x.desc || '已有因果往来')
      };
      merged.push(seen[n]);
    });
    if(!merged.length){
      host.innerHTML = '<div class="bh-empty">尚无已记人脉 · 结识同行、街坊或遇异数天骄后自动入册</div>';
      return;
    }
    host.innerHTML = '<div class="pc-npcs">' + merged.map(function(p){
      var rv = (p.r !== '' && isFinite(Number(p.r))) ? (' · 缘 ' + Math.round(Number(p.r))) : '';
      var rows = [['姓名', p.n], ['身份/关系', p.s + rv], ['近况/备注', p.d || '—']];
      var img = (typeof window.portraitFor === 'function') ? (window.portraitFor(p.n) || '') : '';
      var act = '我设法联系或前往拜访「' + p.n + '」：';
      return '<div class="pc-npc-card" role="button" tabindex="0" data-det="' + encodeURIComponent(p.n) + '" data-rows="' + encodeURIComponent(JSON.stringify(rows)) + '"' + (img ? (' data-img="' + escH(img) + '"') : '') + ' data-act="' + escH(act) + '" data-act-label="联络拜访 ▸">'
        + '<div class="pc-npc-top"><span class="pc-npc-name">' + escH(p.n) + '</span><span class="pc-npc-tag">' + escH(p.s) + escH(rv) + '</span></div>'
        + '<div class="pc-npc-desc">' + escH(p.d) + '</div></div>';
    }).join('') + '</div>';
  }

  /* 3. 单排十卷牙签锦标导航（带古典序数 + 实时朱砂计数角标） */
  function updateTabBadges(){
    if(!window.__bhV) return;
    var V = window.__bhV;
    var bkCnt = (V.book || []).filter(function(b){ var s = typeof b==='string'?'':(b.s||b.stage||''); return String(s||'').trim() && String(s).trim()!=='未契约'; }).length;
    var counts = {
      map: (V.emg || []).length,
      book: bkCnt,
      ghost: (V.ghost || []).length,
      bag: (V.bag || []).length,
      case: (V.task || []).length,
      opt: (V.adv || []).length,
      pact: (V.npc || []).length + (V.rel || []).length
    };
    var meta = {
      map:  ['壹', '舆图'],
      book: ['贰', '真形'],
      ghost:['叁', '鬼口'],
      bag:  ['肆', '行囊'],
      adv:  ['伍', '追迹'],
      case: ['陆', '案卷'],
      fate: ['柒', '命数'],
      world:['捌', '世道'],
      opt:  ['玖', '抉择'],
      pact: ['拾', '契约']
    };
    document.querySelectorAll('#tabs .bh-tab').forEach(function(tab){
      var k = tab.getAttribute('data-p');
      var m = meta[k] || ['', tab.textContent.trim()];
      var n = counts[k] || 0;
      tab.innerHTML = (m[0] ? ('<span class="tb-ord">' + m[0] + '·</span>') : '')
        + '<span>' + escH(m[1]) + '</span>'
        + (n > 0 ? ('<i class="tb-cnt">' + n + '</i>') : '');
    });
  }

  /* 4. 外链头像断网优雅降级（杜绝破损图片小图标） */
  window.addEventListener('error', function(ev){
    var el = ev && ev.target;
    if(!el || el.tagName !== 'IMG') return;
    if(el.parentNode && el.parentNode.classList && el.parentNode.classList.contains('bh-gt-line')){
      var dot = document.createElement('span');
      dot.className = 'gl-d';
      dot.style.background = el.style.borderColor || '#9E2A1F';
      el.parentNode.replaceChild(dot, el);
    } else if(el.parentNode && el.parentNode.children && el.parentNode.children.length === 1 && el.parentNode.tagName === 'DIV'){
      el.parentNode.style.display = 'none';
    } else {
      el.style.display = 'none';
    }
  }, true);

  window.__bhRefreshV3 = refreshAllV3;
  function refreshAllV3(){
    try{ setupWidescreenLayouts(); }catch(e){}
    try{ tidyTopTimeBar(); }catch(e){}
    try{ renderNpcAndRel(); }catch(e){}
    try{ updateTabBadges(); }catch(e){}
  }

  if(window.BH && typeof window.BH.set === 'function'){
    var _origSet = window.BH.set;
    window.BH.set = function(v){
      var r = _origSet.apply(this, arguments);
      refreshAllV3();
      return r;
    };
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', refreshAllV3);
  else setTimeout(refreshAllV3, 20);
})();
;

window.__BH_UI_LOADED = true;

